insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('stress-signature-body-map', 'Stress Signature Body Map', 'worksheet'::resource_kind, 'A client marks where stress shows up in the body, thoughts and actions, and what each signal is asking for.', 'Help a client notice their own early stress signals before they build.', array['Adults', 'Teens']::text[], '25 minutes', 'Hand the client a simple body outline and invite them to mark where stress tends to show up, then add thoughts and behaviors beside it. Most clients name two or three signals quickly and need a prompt for the quieter ones. Treat their map as their own language for stress, and revisit it after a week of noticing.', '[{"id": "f0", "type": "textarea", "label": "Where in my body I notice stress first"}, {"id": "f1", "type": "textarea", "label": "Thoughts that show up when stress is building"}, {"id": "f2", "type": "textarea", "label": "Things I do when stress is high"}, {"id": "f3", "type": "textarea", "label": "What my body seems to be asking for"}, {"id": "f4", "type": "textarea", "label": "One early signal I will watch for this week"}]'::jsonb, array['self-monitoring', 'stress', 'regulation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('support-circles-map', 'Support Circles Map', 'worksheet'::resource_kind, 'Concentric circles help a client place the people and places that offer support at different levels of closeness.', 'Show a client where their support is strong and where it is thin.', array['Adults', 'Teens']::text[], '30 minutes', 'Draw three circles and have the client place names, groups, pets and places in each, from daily support to occasional. Gaps are information, not failure; ask what each circle gives them and what they wish it gave. Finish by choosing one person to reach toward this week and a small first move.', '[{"id": "f0", "type": "textarea", "label": "People closest to me, and what they give me"}, {"id": "f1", "type": "textarea", "label": "People and groups in my middle circle"}, {"id": "f2", "type": "textarea", "label": "Places or routines that support me"}, {"id": "f3", "type": "textarea", "label": "A circle where I wish I had more support"}, {"id": "f4", "type": "textarea", "label": "One small step to reach toward someone this week"}]'::jsonb, array['support', 'connection', 'self-monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('weekly-reset-review-sheet', 'Weekly Reset Review Sheet', 'worksheet'::resource_kind, 'A short end-of-week review of what worked, what drained energy and what to carry into the next week.', 'Give a client a repeatable way to learn from their own week.', array['Adults', 'Teens']::text[], '20 minutes', 'Use this at the end of a session or as a weekly habit the client keeps on their own. Keep entries short and concrete, one line each, so the review stays light. If a client only lists what went wrong, ask for one thing that went even slightly better and build from there.', '[{"id": "f0", "type": "textarea", "label": "Something that went better than I expected"}, {"id": "f1", "type": "textarea", "label": "Something that drained my energy"}, {"id": "f2", "type": "textarea", "label": "A moment I handled in a way I am glad about"}, {"id": "f3", "type": "textarea", "label": "What I want to do differently next week"}, {"id": "f4", "type": "textarea", "label": "One thing I will protect on my calendar"}]'::jsonb, array['routines', 'self-monitoring', 'habits']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('firm-and-kind-boundary-script-builder', 'Firm and Kind Boundary Script Builder', 'worksheet'::resource_kind, 'Clients draft short, kind and firm sentences for the boundaries they want to set with specific people.', 'Help a client put a needed boundary into words they can really say.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick one real situation and build the sentence together: what is happening, what the client needs, and what they will do. Rehearse it aloud in session, since written scripts often sound stiffer than the client expects. Talk through the likely pushback and decide in advance how they will respond.', '[{"id": "f0", "type": "textarea", "label": "The situation where I need a boundary"}, {"id": "f1", "type": "textarea", "label": "What I need, in one clear sentence"}, {"id": "f2", "type": "textarea", "label": "How I could say it kindly and firmly"}, {"id": "f3", "type": "textarea", "label": "What the other person might say back"}, {"id": "f4", "type": "textarea", "label": "What I will do if the boundary is not respected"}]'::jsonb, array['boundaries', 'communication', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('evening-wind-down-planner', 'Evening Wind-Down Planner', 'worksheet'::resource_kind, 'A planner for building a repeatable, screen-light routine for the hour before sleep.', 'Help a client design a wind-down routine that fits their actual evenings.', array['Adults', 'Teens']::text[], '20 minutes', 'Start from what the client already does at night rather than an ideal routine. Have them pick two or three steps they are willing to try, set a start time, and plan for the evening when it falls apart. Review it a week later and adjust without turning it into a test of willpower.', '[{"id": "f0", "type": "textarea", "label": "What my evenings look like right now"}, {"id": "f1", "type": "textarea", "label": "Two or three calming steps I am willing to try"}, {"id": "f2", "type": "textarea", "label": "The time I will start winding down"}, {"id": "f3", "type": "textarea", "label": "What usually gets in the way"}, {"id": "f4", "type": "textarea", "label": "My plan for a night when the routine falls apart"}]'::jsonb, array['routines', 'sleep', 'habits']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('thought-record-split-screen', 'Thought Record Split Screen', 'cbt'::resource_kind, 'A two-column thought record that keeps the situation, the thought and a balanced reply side by side.', 'Teach a client the core thought-record steps in a form they can finish in minutes.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through one recent situation together before the client tries it alone. Keep the left side for the situation, feeling and automatic thought, and the right side for evidence on both sides and a balanced reply. Clients often skip the feeling rating, so ask for it first and again at the end.', '[{"id": "f0", "type": "textarea", "label": "The situation, in one or two sentences"}, {"id": "f1", "type": "textarea", "label": "The feeling and how strong it was, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "The thought that went through my mind"}, {"id": "f3", "type": "textarea", "label": "Evidence that fits the thought and evidence that does not"}, {"id": "f4", "type": "textarea", "label": "A balanced reply, and how strong the feeling is now"}]'::jsonb, array['core CBT', 'thinking traps', 'monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('behavioral-experiment-planner', 'Behavioral Experiment Planner', 'cbt'::resource_kind, 'A planning sheet for testing a prediction in real life: what to try, what to expect and what happened.', 'Help a client test a belief through action instead of argument.', array['Adults', 'Teens']::text[], '30 minutes', 'Choose a prediction the client holds strongly and design a small, specific test that could go either way. Be clear about what they expect and how they will know. Afterward, spend more time on what they learned than on whether the prediction was right, and plan the next experiment from it.', '[{"id": "f0", "type": "textarea", "label": "The prediction I want to test"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "The experiment I will try, and when"}, {"id": "f3", "type": "textarea", "label": "What I expect will happen"}, {"id": "f4", "type": "textarea", "label": "What actually happened and what I learned"}]'::jsonb, array['core CBT', 'experiments', 'monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('shared-responsibility-slices-chart', 'Shared Responsibility Slices Chart', 'cbt'::resource_kind, 'Clients divide up a circle to show all the factors that contributed to an outcome they blame themselves for.', 'Loosen all-or-nothing blame by making every contributing factor visible.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to list every factor first, including their own part, and rank them before drawing slices. Place their own slice last so the picture is not decided in advance. The point is accuracy, not letting them off the hook, so keep room for a share that really is theirs.', '[{"id": "f0", "type": "textarea", "label": "The outcome I blame myself for"}, {"id": "f1", "type": "textarea", "label": "Everything that played a part, including other people and chance"}, {"id": "f2", "type": "textarea", "label": "How I would divide the circle, with my part last"}, {"id": "f3", "type": "textarea", "label": "What I notice when I look at the full picture"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend in my place"}]'::jsonb, array['core CBT', 'thinking traps', 'guilt']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('friend-versus-self-standard-sheet', 'Friend Versus Self Standard Sheet', 'cbt'::resource_kind, 'A sheet that compares the words a client uses with themselves to the words they would offer a friend.', 'Help a client notice a harsher standard for themselves than for others.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to write what they tell themselves about a recent mistake, then what they would say to a close friend in the same spot. Do not rush to the conclusion; let them read the two side by side and say what they see. Close by asking which version they want to practice this week.', '[{"id": "f0", "type": "textarea", "label": "A recent mistake or setback"}, {"id": "f1", "type": "textarea", "label": "What I say to myself about it"}, {"id": "f2", "type": "textarea", "label": "What I would say to a close friend in the same situation"}, {"id": "f3", "type": "textarea", "label": "What I notice when I compare the two"}, {"id": "f4", "type": "textarea", "label": "A sentence I want to practice using with myself"}]'::jsonb, array['core CBT', 'self-talk', 'self-compassion']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('downward-arrow-belief-ladder', 'Downward Arrow Belief Ladder', 'cbt'::resource_kind, 'A stepwise worksheet that follows a thought down to the belief underneath by asking what it would mean.', 'Help a client reach the core belief behind an everyday automatic thought.', array['Adults']::text[], '30 minutes', 'Start with one automatic thought and keep asking, gently, what it would mean about them or their life if it were true. Stop when the answers repeat or the client reaches a short, personal statement. Go slowly and check how they are doing at each step, since this can be tender ground.', '[{"id": "f0", "type": "textarea", "label": "The first thought, as I noticed it"}, {"id": "f1", "type": "textarea", "label": "If that were true, what would it mean?"}, {"id": "f2", "type": "textarea", "label": "And if that were true, what would it mean?"}, {"id": "f3", "type": "textarea", "label": "The belief that sits at the bottom"}, {"id": "f4", "type": "textarea", "label": "How much I believe it, 0 to 100, and where I may have learned it"}]'::jsonb, array['core beliefs', 'core CBT', 'formulation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('leaves-floating-downstream-practice', 'Leaves Floating Downstream Practice', 'act'::resource_kind, 'A guided image of placing thoughts on leaves floating down a stream, with a log of what showed up.', 'Give a client a way to watch thoughts pass without following them.', array['Adults', 'Teens']::text[], '15 minutes', 'Read the image slowly, then ask the client what showed up and what pulled them off the stream. Getting pulled away is the practice, not a mistake, so celebrate every time they noticed and came back. Tell them thoughts do not have to be pushed away or analyzed in this exercise.', '[{"id": "f0", "type": "textarea", "label": "What thoughts floated by"}, {"id": "f1", "type": "textarea", "label": "What pulled me off the stream"}, {"id": "f2", "type": "textarea", "label": "How I noticed I had drifted and came back"}, {"id": "f3", "type": "textarea", "label": "What it was like to watch instead of follow"}, {"id": "f4", "type": "textarea", "label": "Where I could use this in my week"}]'::jsonb, array['core ACT', 'defusion', 'mindfulness']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('pushing-away-hands-demonstration', 'Pushing Away Hands Demonstration', 'act'::resource_kind, 'A two-step demonstration of how hard it is to hold difficult feelings away, and what changes when they are carried.', 'Let a client feel, not just hear, the cost of struggling with an inner experience.', array['Adults', 'Teens']::text[], '20 minutes', 'Hand the client a pillow or folder as a stand-in for a hard feeling and have them push it away with their arms straight, then hold it in their lap. Ask what each posture costs them and what they can do with free hands. Keep it playful and let them reach their own conclusion.', '[{"id": "f0", "type": "textarea", "label": "A feeling I often try to push away"}, {"id": "f1", "type": "textarea", "label": "What pushing it away costs me"}, {"id": "f2", "type": "textarea", "label": "What it was like to hold it in my lap"}, {"id": "f3", "type": "textarea", "label": "What my hands could do while I carry it"}, {"id": "f4", "type": "textarea", "label": "One situation where I could carry it instead of pushing"}]'::jsonb, array['core ACT', 'acceptance', 'willingness']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('committed-action-small-steps-planner', 'Committed Action Small Steps Planner', 'act'::resource_kind, 'A sheet that breaks a value into one tiny action, a time and a plan for obstacles.', 'Turn a valued direction into steps small enough to take this week.', array['Adults', 'Teens']::text[], '25 minutes', 'Begin with a value the client has named and shrink the action until it feels almost too small. Ask when and where it will happen, and which thoughts or feelings will show up and what they will do with them. Review it next session and celebrate any attempt, since the learning is in the doing.', '[{"id": "f0", "type": "textarea", "label": "A value I care about"}, {"id": "f1", "type": "textarea", "label": "A small action that fits it"}, {"id": "f2", "type": "textarea", "label": "When and where I will do it"}, {"id": "f3", "type": "textarea", "label": "Thoughts or feelings that may come along"}, {"id": "f4", "type": "textarea", "label": "What I will do with them and how I will mark it done"}]'::jsonb, array['core ACT', 'values', 'committed action']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('values-card-sort-reflection', 'Values Card Sort Reflection', 'act'::resource_kind, 'A reflection sheet that follows a card sort of values, naming the top few and how they show up in daily life.', 'Help a client name what matters most in their own words.', array['Adults', 'Teens']::text[], '35 minutes', 'Have the client sort value cards into three piles: very important, somewhat important and not for me, and then narrow to five. For each, ask how it shows up now. Gaps between a value and daily life are a conversation, not a grade, and the client decides which gap matters.', '[{"id": "f0", "type": "textarea", "label": "My top five values, in my own words"}, {"id": "f1", "type": "textarea", "label": "How one of them shows up in my life now"}, {"id": "f2", "type": "textarea", "label": "One place a value is missing in my days"}, {"id": "f3", "type": "textarea", "label": "Whose voice I hear when I think about each value"}, {"id": "f4", "type": "textarea", "label": "One value I want to give more room this month"}]'::jsonb, array['values', 'core ACT', 'self-monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('choice-point-diagram-worksheet', 'Choice Point Diagram Worksheet', 'act'::resource_kind, 'A diagram that maps a hard moment into the thoughts and urges that pull away from values and the moves that move toward them.', 'Help a client spot the fork between away moves and toward moves.', array['Adults', 'Teens']::text[], '30 minutes', 'Draw a fork and ask the client to pick one hard recent moment. On one side list what pulls them away (thoughts, feelings, urges, actions) and on the other what a toward move would look like. Neither side is bad; the question is which one fits who they want to be in that moment.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I want to look at"}, {"id": "f1", "type": "textarea", "label": "Thoughts, feelings and urges that showed up"}, {"id": "f2", "type": "textarea", "label": "What I did that moved me away from what matters"}, {"id": "f3", "type": "textarea", "label": "What a toward move could have been"}, {"id": "f4", "type": "textarea", "label": "What would help me notice the fork next time"}]'::jsonb, array['core ACT', 'values', 'choice point']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('please-skills-weekly-tracker', 'PLEASE Skills Weekly Tracker', 'dbt'::resource_kind, 'A weekly tracker for the self-care basics of the PLEASE skills: body care, sleep, movement and substances.', 'Help a client see how basics shape their emotional ups and downs.', array['Adults', 'Teens']::text[], 'One week', 'Have the client fill the tracker daily for a week and bring it to session to look for links between basics and emotional intensity. Stay curious about patterns rather than correcting them. Pick one area to adjust and keep the goal small enough that they are likely to succeed.', '[{"id": "f0", "type": "textarea", "label": "How I looked after my body this week"}, {"id": "f1", "type": "textarea", "label": "How my sleep went most nights"}, {"id": "f2", "type": "textarea", "label": "How much I moved my body and how it felt"}, {"id": "f3", "type": "textarea", "label": "What I noticed about my moods on easier days"}, {"id": "f4", "type": "textarea", "label": "One basic I will adjust next week"}]'::jsonb, array['regulation', 'skills', 'self-monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('wise-mind-check-in-card', 'Wise Mind Check-In Card', 'dbt'::resource_kind, 'A pocket card that walks a client from emotion mind and reasonable mind to wise mind in a few questions.', 'Give a client a quick routine for pausing and finding a balanced response.', array['Adults', 'Teens']::text[], '10 minutes', 'Introduce the card in session with a real decision the client is facing, and have them sit quietly before answering. Ask what emotion mind says, what reasonable mind says and what wise mind adds. Many clients need practice to tell the three apart, so use easy situations first.', '[{"id": "f0", "type": "textarea", "label": "What my emotion mind is saying"}, {"id": "f1", "type": "textarea", "label": "What my reasonable mind is saying"}, {"id": "f2", "type": "textarea", "label": "What my wise mind adds when I get quiet"}, {"id": "f3", "type": "textarea", "label": "What I will do next based on that"}, {"id": "f4", "type": "textarea", "label": "How the decision feels in my body"}]'::jsonb, array['mindfulness', 'regulation', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('coping-ahead-for-radical-acceptance-plan', 'Coping Ahead for Radical Acceptance Plan', 'dbt'::resource_kind, 'A plan to rehearse accepting a situation that cannot be changed, with the thoughts and actions that will help.', 'Help a client prepare to meet a hard, unchangeable moment with acceptance.', array['Adults']::text[], '30 minutes', 'Choose a situation the client expects to face and cannot change. Have them name what they cannot control, the urges that will show up and the acceptance moves they will use, such as half smile or willing hands. Rehearse it in imagination, then check in after the event.', '[{"id": "f0", "type": "textarea", "label": "The situation I expect to face"}, {"id": "f1", "type": "textarea", "label": "What I cannot change about it"}, {"id": "f2", "type": "textarea", "label": "Urges I expect to feel"}, {"id": "f3", "type": "textarea", "label": "Acceptance moves I will use"}, {"id": "f4", "type": "textarea", "label": "How I will care for myself afterward"}]'::jsonb, array['distress tolerance', 'acceptance', 'coping ahead']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('give-skills-conversation-rehearsal', 'GIVE Skills Conversation Rehearsal', 'dbt'::resource_kind, 'A rehearsal sheet for a conversation in which a client wants to keep the relationship while asking for something.', 'Help a client practice staying gentle and interested while making a request.', array['Adults', 'Teens']::text[], '30 minutes', 'Use a real, upcoming conversation and rehearse it in a role-play. Walk through being gentle, acting interested, validating and keeping an easy manner. Switch roles so the client feels the other side. Debrief on what felt natural and what needs more practice.', '[{"id": "f0", "type": "textarea", "label": "The conversation I want to have"}, {"id": "f1", "type": "textarea", "label": "How I will stay gentle"}, {"id": "f2", "type": "textarea", "label": "How I will show I am interested"}, {"id": "f3", "type": "textarea", "label": "What I can validate about the other person"}, {"id": "f4", "type": "textarea", "label": "What I will ask for and how I will end the conversation"}]'::jsonb, array['DEAR MAN', 'communication', 'interpersonal']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('five-senses-self-soothe-kit-sheet', 'Five Senses Self-Soothe Kit Sheet', 'dbt'::resource_kind, 'A planning sheet for building a small kit that soothes through sight, sound, smell, taste and touch.', 'Help a client prepare soothing items before distress arrives.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to pick one or two items for each sense and decide where each lives so it is easy to reach. Test the items in session when possible. Remind them that what soothes is personal, and swap out anything that does not help after a week of trying.', '[{"id": "f0", "type": "textarea", "label": "Something calming to look at"}, {"id": "f1", "type": "textarea", "label": "A sound that settles me"}, {"id": "f2", "type": "textarea", "label": "A scent I like"}, {"id": "f3", "type": "textarea", "label": "A taste that soothes me"}, {"id": "f4", "type": "textarea", "label": "Something comforting to touch, and where I will keep my kit"}]'::jsonb, array['distress tolerance', 'self-soothing', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('weekly-state-of-the-union-card', 'Weekly State of the Union Card', 'couples'::resource_kind, 'A short, structured weekly talk for partners to share appreciation, concerns and one request.', 'Give partners a calm, predictable space for small issues before they grow.', array['Couples']::text[], '30 minutes weekly', 'Set a time, a place and a limit of thirty minutes. Each partner shares one appreciation, one concern in soft words and one request, while the other listens and reflects back before replying. Coach them to keep concerns to the week, not the whole history, and end with something warm.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciated this week"}, {"id": "f1", "type": "textarea", "label": "Partner B: something I appreciated this week"}, {"id": "f2", "type": "textarea", "label": "Partner A: one concern, gently put"}, {"id": "f3", "type": "textarea", "label": "Partner B: one concern, gently put"}, {"id": "f4", "type": "textarea", "label": "What we each will do differently this week"}]'::jsonb, array['communication', 'connection', 'routines']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('turning-toward-bids-log', 'Turning Toward Bids Log', 'couples'::resource_kind, 'A log where partners notice small bids for attention and how each one was answered.', 'Help partners spot and answer everyday bids for connection.', array['Couples']::text[], 'One week', 'Explain that a bid is any small reach for attention, from a comment to a sigh. For a week, each partner jots down bids they made and bids they noticed, and how each was met. Review the log together in session and celebrate the turns toward, even tiny ones, rather than counting misses.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a bid I made and how it was met"}, {"id": "f1", "type": "textarea", "label": "Partner B: a bid I made and how it was met"}, {"id": "f2", "type": "textarea", "label": "A bid I noticed from my partner and what I did"}, {"id": "f3", "type": "textarea", "label": "A bid I missed and what I would do now"}, {"id": "f4", "type": "textarea", "label": "One way we will notice bids more this week"}]'::jsonb, array['Gottman', 'connection', 'communication']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('shared-dreams-conversation-sheet', 'Shared Dreams Conversation Sheet', 'couples'::resource_kind, 'A guided conversation for partners to share hopes, and the stories behind them, without trying to solve anything.', 'Help partners understand what the other is hoping for.', array['Couples']::text[], '45 minutes', 'Have each partner pick a dream, from small to large, and share the story behind it while the other asks open questions. The aim is to understand, not to plan or negotiate. If a dream clashes with the other partner, note it kindly and bring it back for another day.', '[{"id": "f0", "type": "textarea", "label": "A dream I have for our life together"}, {"id": "f1", "type": "textarea", "label": "The story behind that dream"}, {"id": "f2", "type": "textarea", "label": "What it would mean to me to live it"}, {"id": "f3", "type": "textarea", "label": "A question I want to ask my partner about theirs"}, {"id": "f4", "type": "textarea", "label": "One small way we can support each other''s dreams this month"}]'::jsonb, array['connection', 'Gottman', 'communication']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('soft-startup-rewrite-sheet', 'Soft Startup Rewrite Sheet', 'couples'::resource_kind, 'A sheet for turning a harsh opener into a gentle one that names a feeling and a request.', 'Help partners start hard conversations in a way that keeps them talking.', array['Couples']::text[], '25 minutes', 'Have each partner write a harsh opener they have used, then rewrite it as an I-feel statement about a specific situation with a clear request. Role-play both versions and let the listener report how each landed. Expect it to feel awkward at first and encourage practice on small topics.', '[{"id": "f0", "type": "textarea", "label": "A harsh opener I have used"}, {"id": "f1", "type": "textarea", "label": "What I was really feeling underneath"}, {"id": "f2", "type": "textarea", "label": "A soft startup version: I feel, about, I need"}, {"id": "f3", "type": "textarea", "label": "How it felt to hear my partner rewrite theirs"}, {"id": "f4", "type": "textarea", "label": "A small topic where we can practice this week"}]'::jsonb, array['Gottman', 'conflict', 'communication']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('household-mental-load-map', 'Household Mental Load Map', 'couples'::resource_kind, 'A map of the invisible planning, remembering and deciding that keeps a home running, and who carries it.', 'Make the mental load visible so partners can share it fairly.', array['Couples']::text[], '40 minutes', 'Ask each partner to list tasks, then mark the ones that also take noticing, planning and remembering. Compare maps without blame; the surprise is often that one partner never saw the load. Choose two items to hand over completely, including the thinking, and revisit in a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I carry, including the planning"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I carry, including the planning"}, {"id": "f2", "type": "textarea", "label": "Tasks neither of us notices until they go wrong"}, {"id": "f3", "type": "textarea", "label": "Two tasks we will fully hand over"}, {"id": "f4", "type": "textarea", "label": "How we will check in about how it feels"}]'::jsonb, array['routines', 'boundaries', 'communication']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('feelings-monster-puppet-craft', 'Feelings Monster Puppet Craft', 'kids'::resource_kind, 'A child builds a puppet from a paper bag and uses it to show different feelings.', 'Give a child a playful way to name and show feelings.', array['Children']::text[], '30 minutes', 'Provide a paper bag, markers, paper scraps and glue, and let the child decorate the monster. Have the puppet show a feeling the child picks, then ask the puppet what it needs. The parent joins in by asking the puppet gentle questions and does not correct anything. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What my monster looks like"}, {"id": "f1", "type": "textarea", "label": "A feeling my monster has today"}, {"id": "f2", "type": "textarea", "label": "What my monster needs when it feels that way"}, {"id": "f3", "type": "textarea", "label": "What my parent can do to help my monster"}, {"id": "f4", "type": "textarea", "label": "A feeling I want my monster to show next time"}]'::jsonb, array['children', 'play', 'emotion identification']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('settling-glitter-bottle-craft', 'Settling Glitter Bottle Craft', 'kids'::resource_kind, 'A child makes a jar of water and glitter and watches it settle while practicing slow breathing.', 'Give a child something to watch and do that helps them settle.', array['Children']::text[], '30 minutes', 'Fill a sealed jar with warm water, clear glue and glitter, then shake it and watch the glitter settle together. Pair it with slow breathing and the idea that busy feelings settle with time. The parent makes one too and practices with the child at home when upset feelings show up.', '[{"id": "f0", "type": "textarea", "label": "What my jar looks like when it is shaken"}, {"id": "f1", "type": "textarea", "label": "What happens when I wait and breathe"}, {"id": "f2", "type": "textarea", "label": "A time my feelings felt shaken up"}, {"id": "f3", "type": "textarea", "label": "What helps my feelings settle"}, {"id": "f4", "type": "textarea", "label": "When I will use my jar at home"}]'::jsonb, array['children', 'play', 'regulation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('kindness-paper-chain-craft', 'Kindness Paper Chain Craft', 'kids'::resource_kind, 'A child adds a paper link for each kind act they do or notice, building a chain.', 'Help a child notice kindness given and received.', array['Children']::text[], 'One week', 'Cut strips of colored paper and set a spot for the chain at home. Each time the child does, sees or receives something kind, they write or draw it on a link. The parent adds links too, and the family reads the chain together. Keep it about noticing, never a contest or a reward chart.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f2", "type": "textarea", "label": "A kind thing I saw"}, {"id": "f3", "type": "textarea", "label": "How it felt to do something kind"}, {"id": "f4", "type": "textarea", "label": "One kind thing I want to do this week"}]'::jsonb, array['children', 'play', 'connection']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('my-helpers-hand-drawing', 'My Helpers Hand Drawing', 'kids'::resource_kind, 'A child traces a hand and writes a trusted person on each finger, then decorates it.', 'Help a child name the people they can go to for help.', array['Children']::text[], '20 minutes', 'Trace the child hand and have them write or draw one helper per finger, such as family, teachers and friends. Ask what each helper does and when the child could go to them. The parent sees the drawing and thanks the helpers. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "My first helper and how they help"}, {"id": "f1", "type": "textarea", "label": "My second helper and how they help"}, {"id": "f2", "type": "textarea", "label": "A helper at school"}, {"id": "f3", "type": "textarea", "label": "A helper at home"}, {"id": "f4", "type": "textarea", "label": "What I can say when I need help"}]'::jsonb, array['children', 'safety', 'trust']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('courage-treasure-map-drawing', 'Courage Treasure Map Drawing', 'kids'::resource_kind, 'A child draws a treasure map with brave steps along the path to a goal.', 'Help a child see a scary goal as a path of small brave steps.', array['Children']::text[], '30 minutes', 'Invite the child to draw an island with a treasure that stands for something they want to do, and to mark small stops along the path. Ask what would make each stop easier. The parent chooses a stop to cheer for at home and notes the small brave things the child tries.', '[{"id": "f0", "type": "textarea", "label": "The treasure I want to reach"}, {"id": "f1", "type": "textarea", "label": "The first small stop on my map"}, {"id": "f2", "type": "textarea", "label": "A tricky spot on the path"}, {"id": "f3", "type": "textarea", "label": "Who can walk with me"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself to stay brave"}]'::jsonb, array['children', 'play', 'exposure']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('emotion-detective-mystery-game', 'Emotion Detective Mystery Game', 'game'::resource_kind, 'Players read short scenes and use clues to guess the feeling behind them.', 'Build emotion-reading skills through play in a group or family.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Prepare short scene cards with clues such as a body posture, a tone or a situation. Players take turns reading a card and the others guess the feeling and the clue that led them there. Debrief on how the same clue can mean different things and how we check by asking.', '[{"id": "f0", "type": "textarea", "label": "A clue that helped me guess a feeling"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard to guess"}, {"id": "f2", "type": "textarea", "label": "A time someone read my feeling correctly"}, {"id": "f3", "type": "textarea", "label": "A time someone misread my feeling"}, {"id": "f4", "type": "textarea", "label": "How I could check a feeling by asking"}]'::jsonb, array['group', 'emotion identification', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('skill-spinner-game', 'Skill Spinner Game', 'game'::resource_kind, 'Players spin for a coping skill, then describe when they would use it and try it out.', 'Help a group practice a range of coping skills in a low-pressure way.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Divide a paper plate into eight skills and use a paper-clip spinner. On a turn, the player describes a time the skill might help and the group tries it for one minute. Passing is always allowed. Debrief on which skills felt useful and which felt strange.', '[{"id": "f0", "type": "textarea", "label": "A skill I landed on"}, {"id": "f1", "type": "textarea", "label": "When I could use it"}, {"id": "f2", "type": "textarea", "label": "What it was like to try it"}, {"id": "f3", "type": "textarea", "label": "A skill I would like to learn better"}, {"id": "f4", "type": "textarea", "label": "A skill I would teach to someone else"}]'::jsonb, array['coping skills', 'group', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('two-truths-and-a-value-game', 'Two Truths and a Value Game', 'game'::resource_kind, 'Players share two true things and one value, and the group guesses which one is the value.', 'Help a group get comfortable talking about what matters to them.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Each player writes two true facts about themselves and one value, the way they would say it, and reads them aloud in random order. Others guess which is the value and ask one question about it. Debrief on how it felt to name what matters and to hear others do the same.', '[{"id": "f0", "type": "textarea", "label": "Two true things about me"}, {"id": "f1", "type": "textarea", "label": "One thing that matters to me"}, {"id": "f2", "type": "textarea", "label": "What others guessed and what surprised me"}, {"id": "f3", "type": "textarea", "label": "What I learned about someone else"}, {"id": "f4", "type": "textarea", "label": "A value I heard that I want to remember"}]'::jsonb, array['values', 'group', 'connection']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('cooperative-calm-down-race', 'Cooperative Calm-Down Race', 'game'::resource_kind, 'A team game where players pass objects while using calming breaths, with the aim of beating their own time.', 'Pair calm breathing with teamwork and light competition against oneself.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Form a circle and pass a soft object while taking one slow breath at each pass. The group tries to better its own time without rushing. Pause to ask how bodies felt at the start and end. Keep the tone cooperative and light, with no losers.', '[{"id": "f0", "type": "textarea", "label": "How my body felt at the start"}, {"id": "f1", "type": "textarea", "label": "How my body felt at the end"}, {"id": "f2", "type": "textarea", "label": "What helped us work as a team"}, {"id": "f3", "type": "textarea", "label": "What happened when we rushed"}, {"id": "f4", "type": "textarea", "label": "Where I could use a calm breath this week"}]'::jsonb, array['regulation', 'group', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('other-side-of-the-story-role-cards', 'Other Side of the Story Role Cards', 'game'::resource_kind, 'Players draw a short scene and speak as another person in it, then compare notes.', 'Help a group practice seeing a situation through another view.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Prepare scene cards with two people in a small disagreement. Players pair up, draw a card, speak as one person, and then swap. Afterward, each says what they noticed about the other view. Keep scenes everyday and avoid anything close to the real conflicts of group members.', '[{"id": "f0", "type": "textarea", "label": "The scene I got"}, {"id": "f1", "type": "textarea", "label": "What I thought the other person was feeling"}, {"id": "f2", "type": "textarea", "label": "What surprised me when I spoke as them"}, {"id": "f3", "type": "textarea", "label": "What changed in how I saw the situation"}, {"id": "f4", "type": "textarea", "label": "Where I could try this in my own life"}]'::jsonb, array['communication', 'group', 'empathy']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('safe-place-detail-builder', 'Safe Place Detail Builder', 'worksheet'::resource_kind, 'A client builds a calm, imagined or real place in sensory detail to return to when they feel on edge.', 'Give a client a steady inner anchor they can reach in session and at home.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to choose a place that feels calm, real or imagined, and describe it through each sense. Choose somewhere with no painful associations, and drop it if any appear. Practice returning to it in session first, and keep the focus on the present, not on any memory.', '[{"id": "f0", "type": "textarea", "label": "The place I chose"}, {"id": "f1", "type": "textarea", "label": "What I see there"}, {"id": "f2", "type": "textarea", "label": "What I hear there"}, {"id": "f3", "type": "textarea", "label": "What I feel and smell there"}, {"id": "f4", "type": "textarea", "label": "How I will practice going there this week"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety', 'coping skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('stuck-point-log-for-today', 'Stuck Point Log for Today', 'cbt'::resource_kind, 'A short log of beliefs that keep feeling true about safety, trust or self, with a gentler alternative to try on.', 'Help a client notice beliefs that tighten after hard experiences and loosen them one at a time.', array['Adults']::text[], '30 minutes', 'Ask the client to name a belief about safety, trust, power or self-blame that comes up today, without describing past events. Look at what evidence supports it in the present and what a more balanced version might be. Pace the work to their comfort and stop if they get overwhelmed.', '[{"id": "f0", "type": "textarea", "label": "A belief that keeps coming up for me"}, {"id": "f1", "type": "textarea", "label": "What it makes me feel and do today"}, {"id": "f2", "type": "textarea", "label": "Present-day evidence that fits and does not fit"}, {"id": "f3", "type": "textarea", "label": "A more balanced way to say it"}, {"id": "f4", "type": "textarea", "label": "How much I believe each version, 0 to 100"}]'::jsonb, array['PTSD and trauma', 'core CBT', 'thinking traps', 'safety']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('making-room-for-hard-memories-practice', 'Making Room for Hard Memories Practice', 'act'::resource_kind, 'A short ACT practice of noticing that memories can be present while the client stays here in this room.', 'Help a client let hard inner experiences be there without being pulled out of the present.', array['Adults']::text[], '20 minutes', 'Never ask the client to retell what happened. Instead, have them notice sensations and thoughts that arise in the present and name them: here is a memory, here is a feeling. Return to the room by describing what they see and hear. Keep sessions short and check their pace often.', '[{"id": "f0", "type": "textarea", "label": "What I notice in my body right now"}, {"id": "f1", "type": "textarea", "label": "A thought or feeling I let stay for a moment"}, {"id": "f2", "type": "textarea", "label": "What I can see and hear in this room"}, {"id": "f3", "type": "textarea", "label": "What helped me stay here"}, {"id": "f4", "type": "textarea", "label": "One thing I will do today that matters to me"}]'::jsonb, array['PTSD and trauma', 'core ACT', 'grounding', 'acceptance']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('window-of-tolerance-day-map', 'Window of Tolerance Day Map', 'dbt'::resource_kind, 'A daily map of hours when a client felt too keyed up, too shut down or in a workable zone.', 'Help a client spot patterns in their state across a day and match a skill to each.', array['Adults', 'Teens']::text[], '25 minutes', 'Give the client a day split into blocks and have them mark where they felt activated, numb or steady. Then choose one skill to try for each state, such as pacing breath for high and movement for low. Look at patterns together and avoid turning the map into a performance score.', '[{"id": "f0", "type": "textarea", "label": "A time today I felt too revved up"}, {"id": "f1", "type": "textarea", "label": "A time today I felt numb or shut down"}, {"id": "f2", "type": "textarea", "label": "A time I felt steady, and what was happening"}, {"id": "f3", "type": "textarea", "label": "A skill I will try when I feel revved up"}, {"id": "f4", "type": "textarea", "label": "A skill I will try when I feel shut down"}]'::jsonb, array['PTSD and trauma', 'window of tolerance', 'regulation', 'grounding']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('safety-bubble-drawing-and-parent-plan', 'Safety Bubble Drawing and Parent Plan', 'kids'::resource_kind, 'A child draws a protective bubble with the people and things that help them feel safe.', 'Give a child a picture of what keeps them safe and a plan their parent can help with.', array['Children']::text[], '30 minutes', 'Invite the child to draw themselves in a bubble with the people, pets and objects that help them feel safe, and talk about the picture without asking about past events. The parent learns what helps and adds it to a calm-down plan. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "What is inside my safety bubble"}, {"id": "f1", "type": "textarea", "label": "Who helps me feel safe"}, {"id": "f2", "type": "textarea", "label": "What I can do when I feel scared"}, {"id": "f3", "type": "textarea", "label": "What my parent can do to help"}, {"id": "f4", "type": "textarea", "label": "A safe place at home"}]'::jsonb, array['PTSD and trauma', 'children', 'safety', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('avoidance-relief-and-cost-ledger', 'Avoidance Relief and Cost Ledger', 'worksheet'::resource_kind, 'A ledger of what a client avoids, the short-term relief and the longer-term cost.', 'Help a client see the trade-off in avoidance without pressure to stop it.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list situations they avoid, rate the relief and the cost to their life, and pick one to look at. This is a map, not a demand. Many clients are surprised how much avoidance has quietly narrowed their days, so leave room for that reaction and let them choose the next step.', '[{"id": "f0", "type": "textarea", "label": "Something I have been avoiding"}, {"id": "f1", "type": "textarea", "label": "How the avoiding helps me in the short term"}, {"id": "f2", "type": "textarea", "label": "What the avoiding costs me"}, {"id": "f3", "type": "textarea", "label": "What I would do if the fear were smaller"}, {"id": "f4", "type": "textarea", "label": "One small step I may be willing to take"}]'::jsonb, array['anxiety', 'avoidance', 'exposure', 'monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('anxiety-prediction-check', 'Anxiety Prediction Check', 'cbt'::resource_kind, 'A log for noting a worry prediction, how likely it feels, and what happened.', 'Let a client check worry predictions against real outcomes over time.', array['Adults', 'Teens']::text[], 'One week', 'The client records each worry as a specific prediction and how likely it feels, then returns to note what happened. After a week, look for patterns, such as how often things went better than feared or how well they coped. Keep it a curiosity exercise rather than a push to stop worrying.', '[{"id": "f0", "type": "textarea", "label": "What I am worried will happen"}, {"id": "f1", "type": "textarea", "label": "How likely it feels, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "If it went badly, how I coped"}, {"id": "f4", "type": "textarea", "label": "What I notice across the week"}]'::jsonb, array['anxiety', 'core CBT', 'monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('worry-time-passenger-practice', 'Worry Time Passenger Practice', 'act'::resource_kind, 'A practice of letting worry ride along while the client does something that matters.', 'Help a client act on what matters while worry is still present.', array['Adults']::text[], '20 minutes', 'Have the client pick a task or value-led action, notice worry thoughts, label them as worry, and keep going. The point is not to quiet worry but to keep the steering wheel. Ask what the worry said and what they did anyway, and note any small step.', '[{"id": "f0", "type": "textarea", "label": "What I want to do that matters"}, {"id": "f1", "type": "textarea", "label": "The worries that came along"}, {"id": "f2", "type": "textarea", "label": "How I labeled them"}, {"id": "f3", "type": "textarea", "label": "What I did anyway"}, {"id": "f4", "type": "textarea", "label": "What I would like to practice next"}]'::jsonb, array['anxiety', 'core ACT', 'defusion', 'values']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('partner-reassurance-habits-sheet', 'Partner Reassurance Habits Sheet', 'couples'::resource_kind, 'Partners look at reassurance, what it gives in the moment and whether a different kind of support fits better.', 'Help partners shape support that comforts without feeding the worry loop.', array['Couples']::text[], '30 minutes', 'Ask the anxious partner what reassurance they seek and how long relief lasts, and the other partner how it feels to give. Agree on a warm alternative, such as listening or a shared calm activity, and trial it for a week. Keep it a team effort against worry, not against the person.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I ask my partner for when I worry"}, {"id": "f1", "type": "textarea", "label": "Partner B: how it feels to be asked"}, {"id": "f2", "type": "textarea", "label": "What helps for a short time and what does not"}, {"id": "f3", "type": "textarea", "label": "A support we will try instead"}, {"id": "f4", "type": "textarea", "label": "How we will check in about it next week"}]'::jsonb, array['anxiety', 'support', 'couples']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('worry-or-fact-card-game', 'Worry or Fact Card Game', 'game'::resource_kind, 'Players sort worry statements into facts, guesses and things they can act on.', 'Help a group tell apart facts, guesses and actionable worries.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Prepare cards with everyday worry statements. Players take turns drawing a card and sorting it into one of three piles, explaining why. Debrief on which pile worries land in most often and what one action pile card they could do today.', '[{"id": "f0", "type": "textarea", "label": "A worry I sorted into the guess pile"}, {"id": "f1", "type": "textarea", "label": "A worry that was a fact"}, {"id": "f2", "type": "textarea", "label": "A worry that I can act on"}, {"id": "f3", "type": "textarea", "label": "What I noticed about my own worries"}, {"id": "f4", "type": "textarea", "label": "One action I will take this week"}]'::jsonb, array['anxiety', 'group', 'thinking traps']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('energy-and-mood-pairing-log', 'Energy and Mood Pairing Log', 'worksheet'::resource_kind, 'A daily log pairing activities with energy and mood to find what lifts and what drains.', 'Give a client data on which small activities tend to help.', array['Adults', 'Teens']::text[], 'One week', 'Have the client log three activities a day with energy and mood ratings. In session, look for ones that nudge things up even a little and plan to add more. Expect low-energy days and treat them as information. If the client mentions thoughts of harming themselves, address it in session, and the log includes the 988 line.', '[{"id": "f0", "type": "textarea", "label": "An activity I did today"}, {"id": "f1", "type": "textarea", "label": "My energy before and after, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "My mood before and after, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "An activity I want more of"}, {"id": "f4", "type": "textarea", "label": "If I ever think about harming myself, I can call or text 988 any time"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring', 'monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('hopeless-thought-reality-check', 'Hopeless Thought Reality Check', 'cbt'::resource_kind, 'A worksheet for looking at a hopeless thought, the evidence and a more balanced view.', 'Help a client find a balanced view of a heavy, discouraging thought.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to write a hopeless thought as they heard it and rate how strongly they believe it. Look for evidence on both sides, including past times things shifted, and craft a balanced statement. Check in about safety; the sheet names 988, and any risk talk belongs in session, not homework.', '[{"id": "f0", "type": "textarea", "label": "The thought, as it showed up"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "Evidence that fits and evidence that does not"}, {"id": "f3", "type": "textarea", "label": "A more balanced view"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['depression', 'core CBT', 'thinking traps', 'safety']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('small-valued-action-under-heavy-mood-sheet', 'Small Valued Action Under Heavy Mood Sheet', 'act'::resource_kind, 'A sheet that pairs one heavy-mood barrier with one tiny action in the direction of a value.', 'Help a client move toward a value even when mood is low.', array['Adults']::text[], '25 minutes', 'Begin with one value, then pick an action so small it can happen in five minutes. Ask what the heavy mood will say and how they will respond. Celebrate the attempt, not the mood after it, and make sure the action is theirs, not an assignment from you.', '[{"id": "f0", "type": "textarea", "label": "A value that matters to me"}, {"id": "f1", "type": "textarea", "label": "A five-minute action toward it"}, {"id": "f2", "type": "textarea", "label": "What my mood will say about doing it"}, {"id": "f3", "type": "textarea", "label": "What I will do with that voice"}, {"id": "f4", "type": "textarea", "label": "When I will do it and who I will tell"}]'::jsonb, array['depression', 'core ACT', 'values', 'behavioral activation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('self-care-floor-checklist', 'Self-Care Floor Checklist', 'dbt'::resource_kind, 'A short checklist of the bare minimum a client wants to protect on very hard days.', 'Give a client a floor of basic care for days when everything feels too much.', array['Adults', 'Teens']::text[], '20 minutes', 'Together, pick three to five basics that count as a good enough day: eating something, taking medication as already directed by their prescriber, getting outside, reaching one person. Keep the list short and forgiving, and revisit it as the client gets stronger.', '[{"id": "f0", "type": "textarea", "label": "What counts as a floor day for me"}, {"id": "f1", "type": "textarea", "label": "Basics I want to protect"}, {"id": "f2", "type": "textarea", "label": "A person I can reach out to on hard days"}, {"id": "f3", "type": "textarea", "label": "A small kindness I can do for myself"}, {"id": "f4", "type": "textarea", "label": "Who will check in on me, and the 988 line if I feel unsafe"}]'::jsonb, array['depression', 'self-care', 'skills', 'regulation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('weather-and-flowers-mood-garden-drawing', 'Weather and Flowers Mood Garden Drawing', 'kids'::resource_kind, 'A child draws a garden whose flowers and weather match how they feel across the week.', 'Help a child show moods through drawing and notice what helps the garden grow.', array['Children', 'Teens']::text[], '25 minutes', 'Invite the child to draw a garden with weather for today and flowers for things that help them feel better. Ask what the garden needs. The parent notices the helpful things and plans one together this week. If a child shares something worrying, follow your reporting duties and your safety plan.', '[{"id": "f0", "type": "textarea", "label": "What the weather is in my garden today"}, {"id": "f1", "type": "textarea", "label": "What flowers are growing"}, {"id": "f2", "type": "textarea", "label": "What the garden needs"}, {"id": "f3", "type": "textarea", "label": "What my parent can do with me this week"}, {"id": "f4", "type": "textarea", "label": "Who I can tell when the weather is stormy"}]'::jsonb, array['depression', 'children', 'play', 'emotion identification']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('time-blindness-estimate-log', 'Time Blindness Estimate Log', 'worksheet'::resource_kind, 'A log of how long a client guesses tasks will take versus how long they did.', 'Help a client learn their real task times to plan with.', array['Adults', 'Teens']::text[], 'One week', 'Have the client guess and then time three everyday tasks a day. In session, compare the numbers without judgment and find the usual gap. Use that gap to set buffer times and alarms. Many clients enjoy this as a game with their own data.', '[{"id": "f0", "type": "textarea", "label": "A task I timed today"}, {"id": "f1", "type": "textarea", "label": "How long I guessed it would take"}, {"id": "f2", "type": "textarea", "label": "How long it really took"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the gap"}, {"id": "f4", "type": "textarea", "label": "How I will plan my time differently"}]'::jsonb, array['ADHD', 'self-monitoring', 'routines', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('start-barrier-thought-sheet', 'Start Barrier Thought Sheet', 'cbt'::resource_kind, 'A sheet that catches thoughts that block starting a task and pairs each with a first tiny step.', 'Help a client get past the thoughts that stall starting.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick a task that has been waiting. Have the client name the thoughts that show up when they think of starting, then rewrite them as a smaller first step they can do in two minutes. Review how it went and what helped, rather than whether the task was finished.', '[{"id": "f0", "type": "textarea", "label": "A task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "Thoughts that show up when I think of starting"}, {"id": "f2", "type": "textarea", "label": "A smaller first step, two minutes or less"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself to begin"}, {"id": "f4", "type": "textarea", "label": "How it went when I tried"}]'::jsonb, array['ADHD', 'core CBT', 'executive skills', 'self-monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('impulse-pause-pocket-card', 'Impulse Pause Pocket Card', 'dbt'::resource_kind, 'A card with a short pause routine for moments of urge to act or speak right away.', 'Give a client a quick pause to use between an urge and an action.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice the pause in session with a few small urges, such as interrupting or grabbing a phone. Teach a short breath and a question about what matters. Keep it brief; a long routine will not be used. Review the real moments they caught.', '[{"id": "f0", "type": "textarea", "label": "An urge I often act on quickly"}, {"id": "f1", "type": "textarea", "label": "What I notice in my body just before"}, {"id": "f2", "type": "textarea", "label": "My short pause: breath and one question"}, {"id": "f3", "type": "textarea", "label": "What I did after pausing"}, {"id": "f4", "type": "textarea", "label": "Where I will put the card so I see it"}]'::jsonb, array['ADHD', 'regulation', 'skills', 'impulse']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('partner-reminder-style-agreement', 'Partner Reminder Style Agreement', 'couples'::resource_kind, 'A sheet for partners to agree on how reminders are given in a way that feels like teamwork, not nagging.', 'Help partners set up reminders that both feel good about.', array['Couples']::text[], '30 minutes', 'Ask the partner with ADHD what kind of reminder helps and what feels like nagging, and the other partner what they need to stop remembering for two. Agree on one tool, such as a shared list, and a trial period. Keep the tone as designing a system together.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what kind of reminder helps me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need so I am not the only one remembering"}, {"id": "f2", "type": "textarea", "label": "Tasks that most need a system"}, {"id": "f3", "type": "textarea", "label": "The tool and timing we will try"}, {"id": "f4", "type": "textarea", "label": "When we will review how it worked"}]'::jsonb, array['ADHD', 'routines', 'couples']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('distraction-spotting-game', 'Distraction Spotting Game', 'game'::resource_kind, 'Players try a short task while others make planned distractions, then talk about what helped them refocus.', 'Let a group practice noticing and returning from distraction.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Give players a short task such as sorting cards while a few distractions, like a noise or a question, happen on schedule. Players note when they got pulled off and how they came back. Debrief on strategies that worked and keep a spirit of fun, not failure.', '[{"id": "f0", "type": "textarea", "label": "What pulled me off the task"}, {"id": "f1", "type": "textarea", "label": "How I noticed"}, {"id": "f2", "type": "textarea", "label": "What helped me come back"}, {"id": "f3", "type": "textarea", "label": "A strategy I heard that I want to try"}, {"id": "f4", "type": "textarea", "label": "Where I could use it this week"}]'::jsonb, array['ADHD', 'group', 'executive skills', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('urge-trigger-timeline', 'Urge Trigger Timeline', 'worksheet'::resource_kind, 'A timeline of the day with markers for when substance use urges tend to arrive and what is happening.', 'Help a client see when urges cluster and plan for those windows.', array['Adults']::text[], '30 minutes', 'Use a simple day-long line and have the client mark urges, people, places and feelings. The aim is a map, not a confession. Pick one or two windows to plan for with a replacement action or a person to call. Use the words substance use and urges, and avoid labels for the person.', '[{"id": "f0", "type": "textarea", "label": "A time of day when urges tend to come"}, {"id": "f1", "type": "textarea", "label": "What is usually happening then"}, {"id": "f2", "type": "textarea", "label": "How strong the urge feels, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I can do in that window"}, {"id": "f4", "type": "textarea", "label": "Who I can contact if the urge is strong"}]'::jsonb, array['addiction', 'urges', 'monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('urge-thought-challenge-sheet', 'Urge Thought Challenge Sheet', 'cbt'::resource_kind, 'A sheet for the thoughts that come with an urge, such as one time will not matter, and a more balanced reply.', 'Help a client find a steadier reply to the thoughts that fuel urges.', array['Adults']::text[], '25 minutes', 'List the thoughts that tend to arrive with an urge and rate how believable they feel in the moment. Look at what happened the last time the client followed such a thought and write a reply they can use. Practice the replies aloud, and keep the focus on substance use and urges.', '[{"id": "f0", "type": "textarea", "label": "A thought that shows up with an urge"}, {"id": "f1", "type": "textarea", "label": "How believable it feels, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What has happened when I followed it"}, {"id": "f3", "type": "textarea", "label": "A reply I can use"}, {"id": "f4", "type": "textarea", "label": "How strong the urge is after the reply"}]'::jsonb, array['addiction', 'urges', 'core CBT']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('willingness-and-urge-surfing-practice', 'Willingness and Urge Surfing Practice', 'act'::resource_kind, 'A short practice for noticing an urge in the body and staying with it while choosing a valued action.', 'Help a client let an urge rise and fall without acting on it.', array['Adults']::text[], '20 minutes', 'Guide the client to notice where the urge sits, how it changes and what thoughts come, naming them without argument. Pair it with a values-based action to do right after. Ask what they learned about the urge and how long it lasted, and keep a warm, nonjudgmental tone.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body"}, {"id": "f1", "type": "textarea", "label": "How it changed as I watched"}, {"id": "f2", "type": "textarea", "label": "Thoughts that came with it"}, {"id": "f3", "type": "textarea", "label": "A valued action I did afterward"}, {"id": "f4", "type": "textarea", "label": "What I learned about my urges"}]'::jsonb, array['addiction', 'urges', 'core ACT']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('partner-support-for-urges-plan', 'Partner Support for Urges Plan', 'couples'::resource_kind, 'A plan for how a partner can respond when urges are hard, agreed in a calm moment.', 'Help partners agree on helpful support around substance use urges.', array['Couples']::text[], '35 minutes', 'In a calm moment, ask the client what support helps when urges are strong and the partner what they can offer without policing. Write a short plan with a signal, a response and what each of them will avoid. Revisit it as needs change. Keep language on urges and substance use.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me when an urge is strong"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer, and what I need for myself"}, {"id": "f2", "type": "textarea", "label": "A signal we will use"}, {"id": "f3", "type": "textarea", "label": "What we will each avoid doing"}, {"id": "f4", "type": "textarea", "label": "When we will review the plan"}]'::jsonb, array['addiction', 'urges', 'couples']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('urge-alternatives-draw-game', 'Urge Alternatives Draw Game', 'game'::resource_kind, 'Players draw an urge scenario card and brainstorm alternatives, then pick the one they would really use.', 'Build a large menu of options for the moment an urge appears.', array['Adults', 'Groups']::text[], '25 minutes', 'Prepare scenario cards describing common situations when substance use urges might arise. Players draw one, list three options and pick the one they would use. The group adds more ideas. Debrief on which options are realistic and which need preparation. Keep it supportive.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "Three options I came up with"}, {"id": "f2", "type": "textarea", "label": "The one I would actually use"}, {"id": "f3", "type": "textarea", "label": "An idea from the group I want to try"}, {"id": "f4", "type": "textarea", "label": "What I need to prepare ahead of time"}]'::jsonb, array['addiction', 'urges', 'group']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('anger-cost-and-benefit-ledger', 'Anger Cost and Benefit Ledger', 'worksheet'::resource_kind, 'A ledger of what anger gets a client and what it costs in relationships and in the body.', 'Help a client weigh what anger does for them and what it takes from them.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to list what anger gives them, such as respect or relief, and what it costs. Both columns are valid and the client should not feel judged. Then ask what need sits under the anger and what other ways could meet it. Stay curious about their view.', '[{"id": "f0", "type": "textarea", "label": "A recent time I was angry"}, {"id": "f1", "type": "textarea", "label": "What anger gave me in that moment"}, {"id": "f2", "type": "textarea", "label": "What it cost me afterward"}, {"id": "f3", "type": "textarea", "label": "The need underneath the anger"}, {"id": "f4", "type": "textarea", "label": "Another way I could meet that need"}]'::jsonb, array['anger management', 'self-monitoring', 'formulation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('anger-hot-thought-rewrite', 'Anger Hot Thought Rewrite', 'cbt'::resource_kind, 'A sheet that catches the demanding thoughts behind anger and rewrites them into flexible ones.', 'Help a client loosen the shoulds and musts that feed anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for a recent angry moment and the thoughts behind it, especially the should and must statements. Rewrite each into a preference, such as I would like, and see how the feeling shifts. Do not argue about whether the client was wronged; focus on what response they want.', '[{"id": "f0", "type": "textarea", "label": "The situation that made me angry"}, {"id": "f1", "type": "textarea", "label": "The thought I had, including any should or must"}, {"id": "f2", "type": "textarea", "label": "How angry I felt, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "A flexible version of the thought"}, {"id": "f4", "type": "textarea", "label": "How angry I feel now, 0 to 100"}]'::jsonb, array['anger management', 'thinking traps', 'core CBT']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('cool-down-skills-menu', 'Cool-Down Skills Menu', 'dbt'::resource_kind, 'A personal menu of fast skills for different levels of anger, from first signs to boiling over.', 'Give a client a ready list of options matched to how hot they are.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client rate anger levels and choose skills for each, such as paced breathing, a walk, cold water or leaving the room. Practice at least one in session. Make sure the menu is theirs and review which items actually worked in the heat of the moment.', '[{"id": "f0", "type": "textarea", "label": "My early signs of anger"}, {"id": "f1", "type": "textarea", "label": "Skills I will use at a mild level"}, {"id": "f2", "type": "textarea", "label": "Skills I will use when it is high"}, {"id": "f3", "type": "textarea", "label": "A skill I will use if I need to leave the room"}, {"id": "f4", "type": "textarea", "label": "Who I can tell my plan to"}]'::jsonb, array['anger management', 'distress tolerance', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('time-out-return-plan', 'Time-Out Return Plan', 'couples'::resource_kind, 'Partners agree on how to call a time-out and, just as important, how to come back to the conversation.', 'Help partners pause heated moments and return to them.', array['Couples']::text[], '30 minutes', 'Work out a signal, a length of break, what each does during it and a set time to return. The return is the key piece, so rehearse the first sentence each will say. Practice with a small issue before a big one and review what made it hard.', '[{"id": "f0", "type": "textarea", "label": "Our time-out signal"}, {"id": "f1", "type": "textarea", "label": "How long our break will be"}, {"id": "f2", "type": "textarea", "label": "What each of us will do during it"}, {"id": "f3", "type": "textarea", "label": "Who comes back and what the first sentence is"}, {"id": "f4", "type": "textarea", "label": "What we will do if one of us is not ready"}]'::jsonb, array['anger management', 'conflict', 'couples']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('volcano-pressure-craft', 'Volcano Pressure Craft', 'kids'::resource_kind, 'A child builds a paper-mache or paper volcano and decides what helps the pressure let out safely.', 'Help a child picture anger building and choose safe ways to let it out.', array['Children']::text[], '35 minutes', 'Build the volcano and talk about the warning signs of building pressure. Have the child choose safe releases, such as squeezing a pillow or running. The parent learns the signs and helps cue a safe release at home. If a child describes harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "My warning signs before I erupt"}, {"id": "f1", "type": "textarea", "label": "What my volcano looks like"}, {"id": "f2", "type": "textarea", "label": "Safe ways I can let the pressure out"}, {"id": "f3", "type": "textarea", "label": "What my parent can say to remind me"}, {"id": "f4", "type": "textarea", "label": "What I will do next time I feel pressure"}]'::jsonb, array['anger management', 'children', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('doubt-and-ritual-pattern-log', 'Doubt and Ritual Pattern Log', 'worksheet'::resource_kind, 'A log of intrusive doubts, the actions that follow and how long relief lasts.', 'Help a client see the cycle of doubt, ritual and brief relief.', array['Adults', 'Teens']::text[], 'One week', 'Have the client log each intrusive thought, the urge to act, what they did and how long relief lasted. The pattern is the point, so avoid arguing with content. Review how often relief faded fast and that the thoughts are unwelcome, not a sign of who they are.', '[{"id": "f0", "type": "textarea", "label": "An unwanted thought or doubt"}, {"id": "f1", "type": "textarea", "label": "The urge I felt"}, {"id": "f2", "type": "textarea", "label": "What I did about it"}, {"id": "f3", "type": "textarea", "label": "How long I felt relief"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the pattern"}]'::jsonb, array['OCD', 'monitoring', 'formulation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('thought-importance-reality-check', 'Thought Importance Reality Check', 'cbt'::resource_kind, 'A sheet that looks at how much importance a client gives to an intrusive thought.', 'Help a client see that having a thought is not the same as meaning it.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client believes a thought says about them and how important it feels. Compare to unwanted thoughts most people have and look at the cost of treating each as a warning. Keep the focus on the relationship with the thought, not on proving it false.', '[{"id": "f0", "type": "textarea", "label": "The unwanted thought"}, {"id": "f1", "type": "textarea", "label": "What I believe it says about me"}, {"id": "f2", "type": "textarea", "label": "How important it feels, 0 to 100"}, {"id": "f3", "type": "textarea", "label": "What happens when I treat it as a warning"}, {"id": "f4", "type": "textarea", "label": "A way to see it as just a thought"}]'::jsonb, array['OCD', 'core CBT', 'thinking traps']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('hello-thought-unwanted-guest-practice', 'Hello Thought Unwanted Guest Practice', 'act'::resource_kind, 'A practice of greeting a sticky thought like an unwelcome guest while continuing the day.', 'Help a client let a sticky thought be there without engaging it.', array['Adults']::text[], '20 minutes', 'Invite the client to say hello thought when it shows up and carry on with a chosen task. They will not like the thought, and it may not leave; the aim is to keep doing what matters. Ask what pulled them back and what helped them return.', '[{"id": "f0", "type": "textarea", "label": "The thought that visits me"}, {"id": "f1", "type": "textarea", "label": "How I greeted it"}, {"id": "f2", "type": "textarea", "label": "What I did while it stayed"}, {"id": "f3", "type": "textarea", "label": "What pulled me into arguing with it"}, {"id": "f4", "type": "textarea", "label": "What matters to me that I kept doing"}]'::jsonb, array['OCD', 'core ACT', 'defusion']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('family-response-plan-sheet', 'Family Response Plan Sheet', 'couples'::resource_kind, 'Partners and family agree on a kind, steady way to respond to reassurance requests and rituals.', 'Help family members support a client without joining rituals.', array['Couples']::text[], '30 minutes', 'Ask the client which responses help and which feed the cycle, and the partner what feels hard to refuse. Agree on a warm, short response to use together. Frame it as teamwork against the cycle, and plan for the first week when it is hardest.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I ask my partner to do"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I do now when asked"}, {"id": "f2", "type": "textarea", "label": "A warm response we can use instead"}, {"id": "f3", "type": "textarea", "label": "What we will do when it is hard"}, {"id": "f4", "type": "textarea", "label": "When we will check in about how it is going"}]'::jsonb, array['OCD', 'family accommodation', 'couples']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('worry-monster-boss-back-craft', 'Worry Monster Boss-Back Craft', 'kids'::resource_kind, 'A child makes a silly worry monster and practices a playful reply, not obeying its demands.', 'Give a child a playful way to talk back to a bossy worry.', array['Children']::text[], '30 minutes', 'Have the child build a funny monster from craft supplies and give it a name. Then practice answering its demands with a silly or calm line. The parent learns to ask what the monster wants and to cheer for answering back rather than giving in. Follow reporting duties if harm is disclosed.', '[{"id": "f0", "type": "textarea", "label": "My worry monster looks like"}, {"id": "f1", "type": "textarea", "label": "What it bosses me to do"}, {"id": "f2", "type": "textarea", "label": "What I can say back to it"}, {"id": "f3", "type": "textarea", "label": "What my parent can do to help"}, {"id": "f4", "type": "textarea", "label": "A time I answered back"}]'::jsonb, array['OCD', 'children', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('panic-cycle-diagram', 'Panic Cycle Diagram', 'worksheet'::resource_kind, 'A diagram of the loop between a body sensation, a frightening thought and rising fear.', 'Help a client see how panic builds and where it can ease.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the loop with the client using their own recent episode: sensation, thought, fear, more sensation. Point out where each can be eased and how fear of the sensation feeds it. Keep the focus on understanding, with no demands to stop panic.', '[{"id": "f0", "type": "textarea", "label": "The first body sensation I noticed"}, {"id": "f1", "type": "textarea", "label": "The thought that followed"}, {"id": "f2", "type": "textarea", "label": "How my fear grew"}, {"id": "f3", "type": "textarea", "label": "Where I could step out of the loop"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['panic attacks', 'formulation', 'psychoeducation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('sensation-reinterpretation-cards', 'Sensation Reinterpretation Cards', 'cbt'::resource_kind, 'Cards that pair a feared reading of a body sensation with a more likely, ordinary one.', 'Help a client practice other readings of body sensations.', array['Adults', 'Teens']::text[], '25 minutes', 'Create cards for each sensation the client fears, with the scary reading on one side and likely ordinary explanations on the other. Review physical concerns with a medical provider as needed. Practice reading aloud and rate belief in each side.', '[{"id": "f0", "type": "textarea", "label": "A body sensation that scares me"}, {"id": "f1", "type": "textarea", "label": "What I fear it means"}, {"id": "f2", "type": "textarea", "label": "Other ordinary explanations"}, {"id": "f3", "type": "textarea", "label": "How much I believe each, 0 to 100"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself next time"}]'::jsonb, array['panic attacks', 'core CBT', 'thinking traps']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-cold-water-skills-card', 'Paced Breathing and Cold Water Skills Card', 'dbt'::resource_kind, 'A card pairing slow exhale breathing and cold water for the surge of panic.', 'Give a client two quick body-based skills for the peak of panic.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice slow exhale breathing in session and try cold water on the face if medically fine for the client. Have them rate how they felt before and after. Make the card small enough to carry and revisit what helped and what did not.', '[{"id": "f0", "type": "textarea", "label": "How strong my panic was, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "My exhale breathing count"}, {"id": "f2", "type": "textarea", "label": "What I tried with cold water"}, {"id": "f3", "type": "textarea", "label": "How strong it was afterward"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this card"}]'::jsonb, array['panic attacks', 'distress tolerance', 'regulation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('partner-panic-plan-card', 'Partner Panic Plan Card', 'couples'::resource_kind, 'A card with what a partner says and does during an episode, and what to avoid.', 'Help partners respond calmly and consistently during panic.', array['Couples']::text[], '25 minutes', 'Ask the client what helps in the moment and what makes it harder, and the partner what feels natural. Write a short script: a calm phrase, a slow breath, a reminder it will pass. Rehearse it once and review how it worked afterward.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me in an episode"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I will say and do"}, {"id": "f2", "type": "textarea", "label": "What we will avoid saying"}, {"id": "f3", "type": "textarea", "label": "How we will know it is passing"}, {"id": "f4", "type": "textarea", "label": "What we will do afterward"}]'::jsonb, array['panic attacks', 'support', 'couples']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('body-sensation-charades', 'Body Sensation Charades', 'game'::resource_kind, 'Players act out ordinary body sensations while others guess, then discuss everyday causes.', 'Normalize body sensations through play.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Make cards with sensations such as racing heart, dizziness or tight chest, plus causes like running, standing quickly or caffeine. Players act or guess, then match with likely causes. Debrief on how sensations come with ordinary activity. Be mindful of members with medical concerns.', '[{"id": "f0", "type": "textarea", "label": "A sensation I acted out or guessed"}, {"id": "f1", "type": "textarea", "label": "An ordinary cause that matches"}, {"id": "f2", "type": "textarea", "label": "A sensation I find scary"}, {"id": "f3", "type": "textarea", "label": "What surprised me"}, {"id": "f4", "type": "textarea", "label": "What I will remember next time I feel it"}]'::jsonb, array['panic attacks', 'group', 'psychoeducation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('parent-trigger-and-response-map', 'Parent Trigger and Response Map', 'worksheet'::resource_kind, 'A map of the moments a parent loses patience, what sets them off and a calmer response to try.', 'Help a parent notice their own triggers and plan a calmer reply.', array['Adults']::text[], '25 minutes', 'Ask the parent to pick a common hard moment, name what happens inside them and what they do. Then plan one calmer move, like a breath or a short phrase. Normalize losing patience and focus on repair, with no shame about past moments.', '[{"id": "f0", "type": "textarea", "label": "A moment I lose patience"}, {"id": "f1", "type": "textarea", "label": "What goes on in me right then"}, {"id": "f2", "type": "textarea", "label": "What I usually do"}, {"id": "f3", "type": "textarea", "label": "A calmer move I could try"}, {"id": "f4", "type": "textarea", "label": "How I will repair afterward if it goes badly"}]'::jsonb, array['parenting', 'regulation', 'repair']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('parent-thought-check-sheet', 'Parent Thought Check Sheet', 'cbt'::resource_kind, 'A sheet for the harsh thoughts a parent has about themselves or their child and a kinder, balanced version.', 'Help a parent loosen thoughts that drive harsh responses.', array['Adults']::text[], '25 minutes', 'Ask for a recent hard moment and the thoughts, like he is doing this on purpose or I am failing. Look at other explanations for the child behavior and for their own. Develop a balanced thought they can bring to the next moment.', '[{"id": "f0", "type": "textarea", "label": "A hard moment with my child"}, {"id": "f1", "type": "textarea", "label": "The thought I had"}, {"id": "f2", "type": "textarea", "label": "Other explanations for what happened"}, {"id": "f3", "type": "textarea", "label": "A balanced version of the thought"}, {"id": "f4", "type": "textarea", "label": "What I want to do next time"}]'::jsonb, array['parenting', 'core CBT', 'thinking traps']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('parent-values-moments-practice', 'Parent Values Moments Practice', 'act'::resource_kind, 'A practice of picking a daily moment to act as the parent the client wants to be.', 'Help a parent connect small daily moments to what they value.', array['Adults']::text[], '20 minutes', 'Ask the parent what kind of parent they want to be in their own words, then choose one daily moment to practice, like bedtime or the first minute after school. Notice what pulls them off course and what helps return. Keep it kind and low pressure.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent I want to be"}, {"id": "f1", "type": "textarea", "label": "A daily moment I will practice in"}, {"id": "f2", "type": "textarea", "label": "What pulls me off course"}, {"id": "f3", "type": "textarea", "label": "What helps me return"}, {"id": "f4", "type": "textarea", "label": "What I noticed after trying"}]'::jsonb, array['parenting', 'core ACT', 'values']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('family-feelings-check-in-cards-craft', 'Family Feelings Check-In Cards Craft', 'kids'::resource_kind, 'Parent and child make a deck of feeling cards for a daily check-in at home.', 'Build a shared language for feelings at home.', array['Children']::text[], '35 minutes', 'Make cards with faces and feeling words together and decorate them. At home, each family member picks a card at dinner and shares a sentence. The parent models first and never fixes or corrects. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Feelings I put on my cards"}, {"id": "f1", "type": "textarea", "label": "A feeling I picked today"}, {"id": "f2", "type": "textarea", "label": "What happened to make me feel that way"}, {"id": "f3", "type": "textarea", "label": "What I want my family to know"}, {"id": "f4", "type": "textarea", "label": "When we will use the cards"}]'::jsonb, array['parenting', 'children', 'emotion identification']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('repair-phrase-role-play-game', 'Repair Phrase Role-Play Game', 'game'::resource_kind, 'Parents take turns drawing a tough moment and practice a repair sentence with the group.', 'Give parents practice finding words for repair after a hard moment.', array['Adults', 'Groups']::text[], '25 minutes', 'Prepare cards of common hard parenting moments. Each parent draws one, offers a short repair sentence, and the group gives warm feedback. Debrief on what made repair feel doable and keep the tone supportive, not competitive.', '[{"id": "f0", "type": "textarea", "label": "The moment I drew"}, {"id": "f1", "type": "textarea", "label": "My repair sentence"}, {"id": "f2", "type": "textarea", "label": "What I heard from the group that I liked"}, {"id": "f3", "type": "textarea", "label": "What makes repair hard for me"}, {"id": "f4", "type": "textarea", "label": "A repair I will try this week"}]'::jsonb, array['parenting', 'repair', 'group']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('support-roster-for-the-first-months', 'Support Roster for the First Months', 'worksheet'::resource_kind, 'A roster of who can help with meals, rest, errands and listening in the first months with a baby.', 'Help a new parent line up real, specific support.', array['Adults']::text[], '30 minutes', 'Ask the parent to list tasks, then match each to a person and a time. Many parents find asking hard, so draft the request words together. Include one person for emotional support and note the number for their provider and, in a crisis, 988 (call or text).', '[{"id": "f0", "type": "textarea", "label": "Tasks I need help with"}, {"id": "f1", "type": "textarea", "label": "Who can do each one"}, {"id": "f2", "type": "textarea", "label": "How I will ask them"}, {"id": "f3", "type": "textarea", "label": "A person I can talk with about how I am really doing"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['perinatal and postpartum', 'support', 'safety']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('good-enough-parent-thought-sheet', 'Good Enough Parent Thought Sheet', 'cbt'::resource_kind, 'A sheet that loosens perfect-parent rules and builds a good-enough standard.', 'Help a new parent ease harsh rules about how they should be doing this.', array['Adults']::text[], '25 minutes', 'Ask for the rules the parent holds, such as I should always know what the baby needs, and look at where they came from and what they cost. Write a good-enough version. Hold space for tiredness and grief about how things are going.', '[{"id": "f0", "type": "textarea", "label": "A rule I hold for myself as a parent"}, {"id": "f1", "type": "textarea", "label": "Where I learned it"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "A good-enough version of the rule"}, {"id": "f4", "type": "textarea", "label": "What I would say to another new parent"}]'::jsonb, array['perinatal and postpartum', 'core beliefs', 'core CBT']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('sleep-protection-and-handoff-plan', 'Sleep Protection and Handoff Plan', 'dbt'::resource_kind, 'A plan for protecting a stretch of sleep and sharing night duties and for what to do when sleep is broken.', 'Help a parent guard rest and regulate during broken nights.', array['Adults', 'Couples']::text[], '25 minutes', 'Work out who covers which stretch of the night, what supports the parent in resting, and a short skill for a hard 3 a.m. moment. Be realistic and flexible. Ask about their mood gently and review the plan after a week.', '[{"id": "f0", "type": "textarea", "label": "The sleep stretch I want to protect"}, {"id": "f1", "type": "textarea", "label": "Who covers the night and how we hand off"}, {"id": "f2", "type": "textarea", "label": "A skill I will use during a hard night"}, {"id": "f3", "type": "textarea", "label": "What helps me fall back asleep"}, {"id": "f4", "type": "textarea", "label": "Who I will tell if things feel heavier"}]'::jsonb, array['perinatal and postpartum', 'regulation', 'routines']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('parent-team-weekly-meeting-sheet', 'Parent Team Weekly Meeting Sheet', 'couples'::resource_kind, 'Partners meet weekly to share how each is doing, divide tasks and plan time together.', 'Keep partners connected as a team in the first months with a baby.', array['Couples']::text[], '30 minutes weekly', 'Ask partners to meet at a calm time and share how each is really doing before planning. Divide the coming week and set a short time for the two of them. Remind them that this season is hard on couples and can feel lonely.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I am really doing"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I am really doing"}, {"id": "f2", "type": "textarea", "label": "What needs dividing this week"}, {"id": "f3", "type": "textarea", "label": "A small moment we will protect for us"}, {"id": "f4", "type": "textarea", "label": "What we appreciate in each other"}]'::jsonb, array['perinatal and postpartum', 'couples', 'connection']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('big-sibling-badge-and-card-craft', 'Big Sibling Badge and Card Craft', 'kids'::resource_kind, 'An older child makes a helper badge and a card for the new baby, naming their own place in the family.', 'Help an older child feel important and heard as the family changes.', array['Children']::text[], '30 minutes', 'Let the child decorate a badge and make a card for the baby, then talk about big feelings too, like jealousy. The parent sets aside a few minutes of one-on-one time daily. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "What my badge says"}, {"id": "f1", "type": "textarea", "label": "What I made for the baby"}, {"id": "f2", "type": "textarea", "label": "A feeling I have about the baby"}, {"id": "f3", "type": "textarea", "label": "What I like doing with my parent alone"}, {"id": "f4", "type": "textarea", "label": "What helps me when I feel left out"}]'::jsonb, array['perinatal and postpartum', 'children', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('strengths-evidence-journal', 'Strengths Evidence Journal', 'worksheet'::resource_kind, 'A journal of daily evidence of strengths, with the moment and the quality it showed.', 'Help a client gather evidence for a fairer view of themselves.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to record one moment a day that shows a quality they value, however small. Review at the end of the week and notice which qualities repeat. If a client brushes things off, ask what a friend would say about the same moment.', '[{"id": "f0", "type": "textarea", "label": "Something I did today"}, {"id": "f1", "type": "textarea", "label": "The quality it shows"}, {"id": "f2", "type": "textarea", "label": "Who noticed or who could have"}, {"id": "f3", "type": "textarea", "label": "What I want to remember"}, {"id": "f4", "type": "textarea", "label": "A strength I saw more than once"}]'::jsonb, array['self-esteem', 'strengths', 'self-monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('worth-is-not-a-scoreboard-practice', 'Worth Is Not a Scoreboard Practice', 'act'::resource_kind, 'A practice of noticing the mind scoring and choosing to act on values anyway.', 'Help a client step off the scoreboard of self-judgment.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to notice when the mind keeps score and give it a name. Then ask what matters to them in that area and what action fits. The aim is not to prove worth but to act on what matters whatever the score says.', '[{"id": "f0", "type": "textarea", "label": "A time my mind kept score"}, {"id": "f1", "type": "textarea", "label": "What the scoreboard said"}, {"id": "f2", "type": "textarea", "label": "What matters to me in that area"}, {"id": "f3", "type": "textarea", "label": "An action that fits what matters"}, {"id": "f4", "type": "textarea", "label": "How I noticed the difference"}]'::jsonb, array['self-esteem', 'core ACT', 'defusion']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('validate-yourself-steps-card', 'Validate Yourself Steps Card', 'dbt'::resource_kind, 'A card with steps for acknowledging feelings and efforts in the way one would for a friend.', 'Teach a client a short routine for self-validation.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through naming the feeling, noting why it makes sense given the situation and offering a kind phrase. Practice on an easy example first. Some clients feel awkward, so let them choose words that sound like them.', '[{"id": "f0", "type": "textarea", "label": "What I am feeling"}, {"id": "f1", "type": "textarea", "label": "Why it makes sense given what happened"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "My own kind sentence"}, {"id": "f4", "type": "textarea", "label": "When I will use this card"}]'::jsonb, array['self-esteem', 'self-compassion', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('me-poster-collage-craft', 'Me Poster Collage Craft', 'kids'::resource_kind, 'A child makes a poster of favorite things, strengths and things people like about them.', 'Help a child build a positive picture of themselves.', array['Children']::text[], '35 minutes', 'Provide poster board, magazines and markers. The child adds favorites, strengths and things others like about them, with the parent adding a few. Hang it where the child sees it. Follow your reporting duties if the child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Things I love"}, {"id": "f1", "type": "textarea", "label": "Things I am good at"}, {"id": "f2", "type": "textarea", "label": "What people like about me"}, {"id": "f3", "type": "textarea", "label": "What my parent wrote"}, {"id": "f4", "type": "textarea", "label": "Where I will hang my poster"}]'::jsonb, array['self-esteem', 'children', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('compliment-catch-circle', 'Compliment Catch Circle', 'game'::resource_kind, 'Players toss a ball and share a genuine strength they notice in someone else, then in themselves.', 'Give a group practice giving and receiving honest positive words.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Players toss a soft ball; the catcher names a strength they notice in the thrower and the thrower says thanks. Include a round where players name one of their own. Debrief on how receiving felt. Allow passing and keep words specific and real.', '[{"id": "f0", "type": "textarea", "label": "A strength someone noticed in me"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it"}, {"id": "f2", "type": "textarea", "label": "A strength I noticed in someone else"}, {"id": "f3", "type": "textarea", "label": "A strength I named for myself"}, {"id": "f4", "type": "textarea", "label": "What I will keep from today"}]'::jsonb, array['self-esteem', 'group', 'strengths']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('social-situation-ladder-planner', 'Social Situation Ladder Planner', 'worksheet'::resource_kind, 'A ladder of social situations from easiest to hardest with a small plan for each rung.', 'Help a client plan gradual practice in the social situations they care about.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client list situations they avoid or endure and rank them by difficulty. Choose a first rung they are willing to try and plan what they will do and how they will look back at it. Let the client set the pace and rework rungs that feel too big.', '[{"id": "f0", "type": "textarea", "label": "Situations that feel hard, easiest to hardest"}, {"id": "f1", "type": "textarea", "label": "The first rung I will try"}, {"id": "f2", "type": "textarea", "label": "What I will do there"}, {"id": "f3", "type": "textarea", "label": "What I fear might happen"}, {"id": "f4", "type": "textarea", "label": "What I will note afterward"}]'::jsonb, array['social anxiety', 'exposure', 'monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('after-event-review-reframe', 'After-Event Review Reframe', 'cbt'::resource_kind, 'A review sheet that replaces harsh post-event replays with a balanced look at what happened.', 'Help a client look at a social event fairly instead of replaying the worst moments.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to write what really happened, what they replayed and what other people might have noticed. Compare the two. Most clients focus on one awkward moment; ask what else happened. Close with one thing to keep and one to try next time.', '[{"id": "f0", "type": "textarea", "label": "What happened at the event"}, {"id": "f1", "type": "textarea", "label": "What I keep replaying"}, {"id": "f2", "type": "textarea", "label": "What others may have noticed or thought"}, {"id": "f3", "type": "textarea", "label": "What went okay"}, {"id": "f4", "type": "textarea", "label": "One thing I will try next time"}]'::jsonb, array['social anxiety', 'thinking traps', 'core CBT']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('showing-up-with-nerves-practice', 'Showing Up With Nerves Practice', 'act'::resource_kind, 'A practice of taking a valued social step while nervous feelings come along.', 'Help a client act on social values with anxiety present.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask what kind of friend, colleague or neighbor the client wants to be and choose a small step. Plan for the nervous thoughts and body feelings, and label them without arguing. Review what they did with them and what mattered about showing up.', '[{"id": "f0", "type": "textarea", "label": "A social step that matters to me"}, {"id": "f1", "type": "textarea", "label": "The nervous thoughts and feelings I expect"}, {"id": "f2", "type": "textarea", "label": "How I will carry them along"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "What mattered about showing up"}]'::jsonb, array['social anxiety', 'core ACT', 'values']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('check-the-facts-social-card', 'Check-the-Facts Social Card', 'dbt'::resource_kind, 'A card for checking whether the story about what others think fits the facts.', 'Teach a client to check their story of a social moment.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through naming the emotion, the event, the interpretation and what the facts show. Ask what other interpretations fit. If the emotion still fits, help the client choose an action. Keep the card small and rehearse it on a past moment first.', '[{"id": "f0", "type": "textarea", "label": "The emotion I felt"}, {"id": "f1", "type": "textarea", "label": "The event, only the facts"}, {"id": "f2", "type": "textarea", "label": "My interpretation"}, {"id": "f3", "type": "textarea", "label": "Other interpretations that could fit"}, {"id": "f4", "type": "textarea", "label": "What I will do"}]'::jsonb, array['social anxiety', 'regulation', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('small-talk-dice-game', 'Small Talk Dice Game', 'game'::resource_kind, 'Players roll dice to pick a topic and a question type and try a short chat with a partner.', 'Give a group low-stakes practice with everyday conversation.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Make dice or cards with topics and question starters. Players pair up and chat for a minute, then swap partners. Praise attempts, not polish. Debrief on what felt easier than expected and what they would try with someone they know.', '[{"id": "f0", "type": "textarea", "label": "A topic I rolled"}, {"id": "f1", "type": "textarea", "label": "A question I asked"}, {"id": "f2", "type": "textarea", "label": "What was easier than I expected"}, {"id": "f3", "type": "textarea", "label": "What was hard"}, {"id": "f4", "type": "textarea", "label": "A conversation I want to try this week"}]'::jsonb, array['social anxiety', 'group', 'exposure']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('grief-waves-and-anchors-log', 'Grief Waves and Anchors Log', 'worksheet'::resource_kind, 'A log of when grief rises, what is happening and what helps it ease.', 'Help a client see grief as waves and find anchors for them.', array['Adults', 'Teens']::text[], 'One week', 'Have the client note when waves arrive, how strong, and what helped. Normalize that grief shows up unexpectedly and differently each day. If a client mentions thoughts of harming themselves, work through it in session; 988 is on the sheet.', '[{"id": "f0", "type": "textarea", "label": "When a wave of grief came"}, {"id": "f1", "type": "textarea", "label": "What was happening"}, {"id": "f2", "type": "textarea", "label": "How strong it felt, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What helped it ease"}, {"id": "f4", "type": "textarea", "label": "If I ever feel unsafe, I can call or text 988"}]'::jsonb, array['grief and loss', 'self-monitoring', 'coping skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('carrying-love-forward-practice', 'Carrying Love Forward Practice', 'act'::resource_kind, 'A practice of finding ways to carry what mattered about a person or relationship into daily life.', 'Help a client keep a valued connection while grieving.', array['Adults']::text[], '25 minutes', 'Ask what the client loved about the person or what they valued, and choose a small way to carry it forward this week. Make room for sadness without asking it to go away. Let the client set pace and the form of remembrance.', '[{"id": "f0", "type": "textarea", "label": "What I loved or valued about them"}, {"id": "f1", "type": "textarea", "label": "A small way to carry it forward"}, {"id": "f2", "type": "textarea", "label": "What feelings came up"}, {"id": "f3", "type": "textarea", "label": "What I want to say to them"}, {"id": "f4", "type": "textarea", "label": "When I will do this"}]'::jsonb, array['grief and loss', 'core ACT', 'values']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('different-grief-styles-conversation-sheet', 'Different Grief Styles Conversation Sheet', 'couples'::resource_kind, 'Partners explain how each grieves, from talking to doing, and what each needs from the other.', 'Help partners understand different ways of grieving.', array['Couples']::text[], '35 minutes', 'Ask each partner how they tend to grieve and what they need. Many couples read different styles as different amounts of love, so name that gently. Agree on one small way to be together in grief and one way to take space.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What I need from my partner"}, {"id": "f3", "type": "textarea", "label": "What I misread about my partner"}, {"id": "f4", "type": "textarea", "label": "One way we will be together this week"}]'::jsonb, array['grief and loss', 'couples', 'communication']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('remembrance-jar-decorating-craft', 'Remembrance Jar Decorating Craft', 'kids'::resource_kind, 'A child decorates a jar and fills it with drawings and notes of memories of someone they miss.', 'Give a child a safe way to remember and talk about a loss.', array['Children']::text[], '35 minutes', 'Let the child decorate a jar and add small drawings or notes of favorite memories. Talk in plain words and let them lead; answer questions simply. The parent adds a memory too and keeps the jar somewhere visible. Follow reporting duties if harm is disclosed.', '[{"id": "f0", "type": "textarea", "label": "Who I am remembering"}, {"id": "f1", "type": "textarea", "label": "A happy memory for the jar"}, {"id": "f2", "type": "textarea", "label": "A feeling I have today"}, {"id": "f3", "type": "textarea", "label": "What I want to ask or say"}, {"id": "f4", "type": "textarea", "label": "What helps me when I miss them"}]'::jsonb, array['grief and loss', 'children', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('remembering-together-memory-game', 'Remembering Together Memory Game', 'game'::resource_kind, 'Group members take turns sharing a memory or quality of someone they lost, with others offering support.', 'Give a grief group a gentle shared ritual of remembering.', array['Adults', 'Groups']::text[], '30 minutes', 'Set ground rules about listening and passing. Players draw prompt cards, such as a favorite saying or a smell, and share if they wish. Others respond with a simple thank you. Debrief on feelings and close with a calming activity.', '[{"id": "f0", "type": "textarea", "label": "The prompt I drew"}, {"id": "f1", "type": "textarea", "label": "A memory I shared or held"}, {"id": "f2", "type": "textarea", "label": "What it felt like to share or listen"}, {"id": "f3", "type": "textarea", "label": "What I heard that helped"}, {"id": "f4", "type": "textarea", "label": "How I want to care for myself tonight"}]'::jsonb, array['grief and loss', 'group', 'support']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('recurring-argument-map', 'Recurring Argument Map', 'worksheet'::resource_kind, 'A map of the steps in a repeating argument, from trigger to blow-up to aftermath.', 'Help a client see the pattern in a repeating argument.', array['Adults', 'Couples']::text[], '30 minutes', 'Have the client draw the typical sequence from the first trigger to the end of the argument and mark where each person feels hurt or afraid. Look for a step where something different could happen. Focus on the pattern, not on assigning blame.', '[{"id": "f0", "type": "textarea", "label": "The topic that keeps coming up"}, {"id": "f1", "type": "textarea", "label": "How it usually starts"}, {"id": "f2", "type": "textarea", "label": "What I feel and need underneath"}, {"id": "f3", "type": "textarea", "label": "How it usually ends"}, {"id": "f4", "type": "textarea", "label": "One step I could change"}]'::jsonb, array['relationship issues', 'conflict', 'formulation']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('assumed-thoughts-check-sheet', 'Assumed Thoughts Check Sheet', 'cbt'::resource_kind, 'A sheet for catching assumptions about what a partner or friend thinks and checking them out.', 'Help a client check an assumption instead of acting on it.', array['Adults']::text[], '25 minutes', 'Ask for a recent moment when the client assumed what the other person was thinking. List other possibilities and a gentle question to ask. Rehearse the question. Remind them that checking is not accusing.', '[{"id": "f0", "type": "textarea", "label": "What I assumed they thought"}, {"id": "f1", "type": "textarea", "label": "What I felt and did"}, {"id": "f2", "type": "textarea", "label": "Other possibilities that could fit"}, {"id": "f3", "type": "textarea", "label": "A gentle question I could ask"}, {"id": "f4", "type": "textarea", "label": "What I learned when I checked"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('dear-man-request-planner', 'DEAR MAN Request Planner', 'dbt'::resource_kind, 'A planner for a clear, respectful request using Describe, Express, Assert, Reinforce, Mindful, Appear confident, Negotiate.', 'Help a client prepare a request using the DEAR MAN steps.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick a real request and build each step together, then role-play it, with you as the other person. Coach tone and body language. Prepare for a no, and practice what to do. Review how it went in the following session.', '[{"id": "f0", "type": "textarea", "label": "The situation I will describe"}, {"id": "f1", "type": "textarea", "label": "How I feel about it"}, {"id": "f2", "type": "textarea", "label": "What I am asking for"}, {"id": "f3", "type": "textarea", "label": "What is in it for them"}, {"id": "f4", "type": "textarea", "label": "What I will do if they say no"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'communication', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('repair-conversation-starter-sheet', 'Repair Conversation Starter Sheet', 'couples'::resource_kind, 'Partners use sentence starters to repair after a hurt, naming their part and what they need.', 'Give partners words to repair after a hard moment.', array['Couples']::text[], '30 minutes', 'Have each partner pick a recent hard moment and use the starters: what I felt, what I contributed, what I need. The listener reflects back before answering. Keep the first try short and practice on small hurts so the habit is ready for big ones.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I felt in that moment"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I felt in that moment"}, {"id": "f2", "type": "textarea", "label": "What I contributed"}, {"id": "f3", "type": "textarea", "label": "What I need now"}, {"id": "f4", "type": "textarea", "label": "What we will do next time"}]'::jsonb, array['relationship issues', 'repair', 'Gottman']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('relationship-skills-role-play-cards', 'Relationship Skills Role-Play Cards', 'game'::resource_kind, 'Players draw scenes of everyday relationship friction and practice a skillful response.', 'Give a group safe practice at responding to friction.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Create scene cards, such as a late friend or a hurtful comment. In pairs, players act the scene twice, once as it often goes and once with a skill. Debrief on what changed. Keep scenes away from group members real conflicts.', '[{"id": "f0", "type": "textarea", "label": "The scene I drew"}, {"id": "f1", "type": "textarea", "label": "How it often goes"}, {"id": "f2", "type": "textarea", "label": "The skill I tried"}, {"id": "f3", "type": "textarea", "label": "What changed"}, {"id": "f4", "type": "textarea", "label": "Where I could use it in real life"}]'::jsonb, array['relationship issues', 'group', 'communication']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('present-day-safety-inventory', 'Present-Day Safety Inventory', 'worksheet'::resource_kind, 'An inventory of what is safe now: places, people, routines and boundaries.', 'Help a client anchor in what is safe in the present.', array['Adults']::text[], '25 minutes', 'Focus entirely on the present: who and what is safe now. Never ask about past events or for details of what happened. Pace gently, and if the client becomes distressed, move to grounding. Review the inventory over time as it grows. 988 is listed for crisis.', '[{"id": "f0", "type": "textarea", "label": "Places where I feel safe now"}, {"id": "f1", "type": "textarea", "label": "People I can trust now"}, {"id": "f2", "type": "textarea", "label": "Routines that help me feel steady"}, {"id": "f3", "type": "textarea", "label": "A boundary I can keep now"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'safety', 'grounding']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('blame-shift-sheet-for-present-beliefs', 'Blame Shift Sheet for Present Beliefs', 'cbt'::resource_kind, 'A sheet to look at beliefs about blame and shame in the present and find a fairer view.', 'Help a client loosen self-blame that shows up today.', array['Adults']::text[], '30 minutes', 'Work only with present-day thoughts about blame, never with recalling events. Ask what the thought says about the client and look at how they would see a friend. Move slowly and offer grounding if the work stirs distress. Never assign the sheet as homework alone.', '[{"id": "f0", "type": "textarea", "label": "A thought about blame or shame that shows up today"}, {"id": "f1", "type": "textarea", "label": "What it makes me feel"}, {"id": "f2", "type": "textarea", "label": "How I would see a friend in the same place"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What I need to feel supported right now"}]'::jsonb, array['sexual abuse', 'core CBT', 'self-compassion']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('values-and-choices-in-my-life-now-practice', 'Values and Choices in My Life Now Practice', 'act'::resource_kind, 'A practice of naming what matters now and the choices that are fully the client own.', 'Help a client reclaim choice and direction in the present.', array['Adults']::text[], '25 minutes', 'Invite the client to name what matters to them now and a small choice that is theirs to make this week. Emphasize choice and pacing. Notice feelings that come up and offer grounding when needed. Do not ask for details of the past.', '[{"id": "f0", "type": "textarea", "label": "What matters to me now"}, {"id": "f1", "type": "textarea", "label": "A choice that is mine this week"}, {"id": "f2", "type": "textarea", "label": "Feelings that came up"}, {"id": "f3", "type": "textarea", "label": "What helps me stay in the present"}, {"id": "f4", "type": "textarea", "label": "Who supports me"}]'::jsonb, array['sexual abuse', 'core ACT', 'values']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('grounding-ladder-card', 'Grounding Ladder Card', 'dbt'::resource_kind, 'A card with grounding steps from light to strong for different levels of distress.', 'Give a client graded grounding options for moments of overwhelm.', array['Adults']::text[], '20 minutes', 'Practice each level in session, from naming things in the room to cold water and movement. Ask what each felt like. Help the client choose which steps to carry. Keep the whole thing about the present moment, never about what happened.', '[{"id": "f0", "type": "textarea", "label": "Light grounding I can try"}, {"id": "f1", "type": "textarea", "label": "Stronger grounding I can try"}, {"id": "f2", "type": "textarea", "label": "How I know I am back in the present"}, {"id": "f3", "type": "textarea", "label": "A person I can contact"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988"}]'::jsonb, array['sexual abuse', 'grounding', 'distress tolerance']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('partner-boundaries-and-pacing-agreement', 'Partner Boundaries and Pacing Agreement', 'couples'::resource_kind, 'Partners agree on pacing, signals and respect for stop in closeness and daily life.', 'Help partners build trust through clear pacing and signals.', array['Couples']::text[], '35 minutes', 'Meet the partners together and ask the survivor what pace and signals help and the partner what they need to understand. Agree on a stop signal that is always honored and on talking about pace outside intimate moments. Never ask for details of the past.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what pace and signals help me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I will do to honor them"}, {"id": "f2", "type": "textarea", "label": "Our stop signal"}, {"id": "f3", "type": "textarea", "label": "How we will talk about pace"}, {"id": "f4", "type": "textarea", "label": "What we appreciate in each other"}]'::jsonb, array['sexual abuse', 'safety', 'couples']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('coping-skill-helpfulness-weekly-tracker', 'Coping Skill Helpfulness Weekly Tracker', 'worksheet'::resource_kind, 'A tracker for trying a skill and rating how much it helped in the moment and later.', 'Help a client learn which skills help in which situations.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to log each skill used, the situation, and ratings before and after. At the review, look for skills that help in some places and not others. Drop what does not help without judgment and add one new one to try.', '[{"id": "f0", "type": "textarea", "label": "A situation where I used a skill"}, {"id": "f1", "type": "textarea", "label": "The skill I used"}, {"id": "f2", "type": "textarea", "label": "My distress before and after, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I noticed later"}, {"id": "f4", "type": "textarea", "label": "A skill I want to try next"}]'::jsonb, array['coping skills', 'self-monitoring', 'skills']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('coping-thoughts-index-cards', 'Coping Thoughts Index Cards', 'cbt'::resource_kind, 'Index cards of short, believable thoughts a client can use when stressed.', 'Give a client a stack of ready coping thoughts they actually believe.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client write a card for each of several stressful situations with a believable coping thought. Test each by asking how strongly they believe it. If they do not believe it, reword it. Encourage them to carry the cards.', '[{"id": "f0", "type": "textarea", "label": "A stressful situation I face"}, {"id": "f1", "type": "textarea", "label": "The thought that makes it harder"}, {"id": "f2", "type": "textarea", "label": "A coping thought I believe"}, {"id": "f3", "type": "textarea", "label": "How much I believe it, 0 to 100"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my cards"}]'::jsonb, array['coping skills', 'core CBT', 'self-talk']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('distract-and-soothe-menu-planner', 'Distract and Soothe Menu Planner', 'dbt'::resource_kind, 'A planner pairing quick distraction ideas with soothing ideas for moments of high distress.', 'Help a client prepare a menu for tough moments.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client for activities that engage the mind and others that comfort the senses, and have them place each on a menu by how much time and energy they take. Try two in session. Remind them that these skills help ride out a wave; they do not solve the problem.', '[{"id": "f0", "type": "textarea", "label": "Activities that take my mind off it"}, {"id": "f1", "type": "textarea", "label": "Things that soothe my senses"}, {"id": "f2", "type": "textarea", "label": "What I can do in five minutes"}, {"id": "f3", "type": "textarea", "label": "What I can do in thirty minutes"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my menu"}]'::jsonb, array['coping skills', 'distress tolerance', 'self-soothing']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('coping-skills-wheel-craft', 'Coping Skills Wheel Craft', 'kids'::resource_kind, 'A child decorates a paper wheel with calming skills and spins it when feelings are big.', 'Give a child a playful way to choose a coping skill.', array['Children']::text[], '35 minutes', 'Cut a paper plate into sections and let the child draw a skill in each, such as breathing, drawing or squeezing a pillow. Practice a few in session. The parent keeps the wheel in a handy spot and spins it together during hard moments. Follow reporting duties if harm is disclosed.', '[{"id": "f0", "type": "textarea", "label": "The skills on my wheel"}, {"id": "f1", "type": "textarea", "label": "The one I like best"}, {"id": "f2", "type": "textarea", "label": "A time I will use it"}, {"id": "f3", "type": "textarea", "label": "What my parent will do"}, {"id": "f4", "type": "textarea", "label": "How I feel after I use a skill"}]'::jsonb, array['coping skills', 'children', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('coping-skill-mime-guessing-game', 'Coping Skill Mime Guessing Game', 'game'::resource_kind, 'Players act out a skill without words while others guess and share when they would use it.', 'Introduce and practice coping skills as a group game.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Prepare cards with skills such as counting breaths or stretching. Players act them out and the group guesses and shares a time it could help. Debrief on favorites and ones to try. Keep it light.', '[{"id": "f0", "type": "textarea", "label": "A skill I acted out or guessed"}, {"id": "f1", "type": "textarea", "label": "When I might use it"}, {"id": "f2", "type": "textarea", "label": "A skill I had not thought of"}, {"id": "f3", "type": "textarea", "label": "A skill I like"}, {"id": "f4", "type": "textarea", "label": "A skill I will try this week"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('fear-thermometer-practice-log', 'Fear Thermometer Practice Log', 'worksheet'::resource_kind, 'A log of fear ratings during repeated practice with a feared situation.', 'Help a client see fear rise and fall over repeated practice.', array['Adults', 'Teens']::text[], 'One week', 'Choose a rung with the client and have them rate fear before, during and after each practice. After several tries, look at the pattern of ratings. Stay with the client pace and avoid pushing for the next rung before they are ready.', '[{"id": "f0", "type": "textarea", "label": "The situation I practiced"}, {"id": "f1", "type": "textarea", "label": "Fear before, during and after, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I feared would happen"}, {"id": "f3", "type": "textarea", "label": "What really happened"}, {"id": "f4", "type": "textarea", "label": "What I will practice next"}]'::jsonb, array['phobias', 'exposure', 'monitoring']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('feared-outcome-probability-sheet', 'Feared Outcome Probability Sheet', 'cbt'::resource_kind, 'A sheet for writing a feared outcome and looking at what has actually happened.', 'Help a client weigh a feared outcome with real-life information.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to state the specific feared outcome, how likely it feels, and what has happened in the past. Look for what they could cope with. Combine with practice, since looking at evidence alone rarely changes a fear.', '[{"id": "f0", "type": "textarea", "label": "The outcome I fear"}, {"id": "f1", "type": "textarea", "label": "How likely it feels, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "What has actually happened before"}, {"id": "f3", "type": "textarea", "label": "How I would cope if it happened"}, {"id": "f4", "type": "textarea", "label": "What I will test by practicing"}]'::jsonb, array['phobias', 'core CBT', 'thinking traps']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('willing-steps-toward-what-matters-practice', 'Willing Steps Toward What Matters Practice', 'act'::resource_kind, 'A practice of choosing a step toward a valued activity while the fear is present.', 'Help a client act on what matters while fear comes along.', array['Adults']::text[], '25 minutes', 'Ask what the fear keeps the client from doing and why that matters. Pick one willing step, name the fear thoughts and body feelings, and take the step with them there. Review what they learned and what mattered.', '[{"id": "f0", "type": "textarea", "label": "What the fear keeps me from"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me"}, {"id": "f2", "type": "textarea", "label": "A willing step I will take"}, {"id": "f3", "type": "textarea", "label": "The fear thoughts and feelings I will carry"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['phobias', 'core ACT', 'values']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('fear-ladder-staircase-craft', 'Fear Ladder Staircase Craft', 'kids'::resource_kind, 'A child builds a paper staircase with steps of facing a fear and moves a figure up as they try each one.', 'Make facing a fear gradual, visible and playful for a child.', array['Children']::text[], '35 minutes', 'Build a staircase from paper or blocks and label each step with a small brave action. The child moves a figure up when ready. The parent does not push and cheers for each try. Plan small rewards of attention. Follow reporting duties if harm is disclosed.', '[{"id": "f0", "type": "textarea", "label": "The fear I am working on"}, {"id": "f1", "type": "textarea", "label": "My first small step"}, {"id": "f2", "type": "textarea", "label": "A step in the middle"}, {"id": "f3", "type": "textarea", "label": "My top step"}, {"id": "f4", "type": "textarea", "label": "What my parent will do to cheer me on"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('brave-challenge-dare-cards-game', 'Brave Challenge Dare Cards Game', 'game'::resource_kind, 'Players draw a small, safe challenge card and report on how it went.', 'Give a group playful, choice-based practice at small brave steps.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Prepare cards with small, safe challenges, such as saying hello to a stranger. Players choose a challenge level, try one before the next session and report. Always allow trading cards and passing. Debrief on what it was like to try.', '[{"id": "f0", "type": "textarea", "label": "The challenge I picked"}, {"id": "f1", "type": "textarea", "label": "How I felt before"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What happened"}, {"id": "f4", "type": "textarea", "label": "What I want to try next"}]'::jsonb, array['phobias', 'group', 'exposure']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('body-talk-trigger-log', 'Body Talk Trigger Log', 'worksheet'::resource_kind, 'A log of moments when body-related comments or media shape mood, and what helped.', 'Help a client notice what stirs body-related thoughts and what soothes them.', array['Adults', 'Teens']::text[], 'One week', 'Ask the client to log moments when comments, images or places stirred body-related thoughts, and what they did. Look for patterns and for what helped. Keep the focus on thoughts, feelings and choices, never on measuring or changing the body.', '[{"id": "f0", "type": "textarea", "label": "A moment that stirred body thoughts"}, {"id": "f1", "type": "textarea", "label": "What was happening around me"}, {"id": "f2", "type": "textarea", "label": "What I felt and thought"}, {"id": "f3", "type": "textarea", "label": "What helped"}, {"id": "f4", "type": "textarea", "label": "A change I could make to my surroundings"}]'::jsonb, array['body image', 'self-monitoring', 'media']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('body-thought-evidence-sheet', 'Body Thought Evidence Sheet', 'cbt'::resource_kind, 'A sheet for looking at a harsh body-related thought and finding a fairer view.', 'Help a client loosen harsh body-related thoughts.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for the thought, where it came from and what it makes them do. Look at how they would speak to a friend and at what the body does for them. Never discuss size, weight or food. Build a fairer thought and practice using it.', '[{"id": "f0", "type": "textarea", "label": "A harsh thought I have about my body"}, {"id": "f1", "type": "textarea", "label": "Where I may have learned it"}, {"id": "f2", "type": "textarea", "label": "What it makes me do"}, {"id": "f3", "type": "textarea", "label": "How I would speak to a friend"}, {"id": "f4", "type": "textarea", "label": "A fairer thought"}]'::jsonb, array['body image', 'core CBT', 'self-talk']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('appreciating-what-my-body-does-practice', 'Appreciating What My Body Does Practice', 'act'::resource_kind, 'A practice of noticing and thanking the body for what it does through the day.', 'Shift attention from how the body looks to what it does.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to notice moments in a day when the body helps them, such as walking, hugging or laughing. Hold the thoughts about looks lightly and ask what matters to them. Review what stood out and what values showed up.', '[{"id": "f0", "type": "textarea", "label": "A moment my body helped me today"}, {"id": "f1", "type": "textarea", "label": "What it let me do"}, {"id": "f2", "type": "textarea", "label": "A thought about looks that showed up"}, {"id": "f3", "type": "textarea", "label": "What I did with that thought"}, {"id": "f4", "type": "textarea", "label": "What matters to me that my body supports"}]'::jsonb, array['body image', 'core ACT', 'values']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('kind-words-about-each-other-exchange', 'Kind Words About Each Other Exchange', 'couples'::resource_kind, 'Partners practice noticing and sharing appreciation that is not about appearance.', 'Help partners build affection and connection beyond looks.', array['Couples']::text[], '30 minutes', 'Have each partner share things they appreciate about the other that are not about looks, such as humor or care. Then each shares what kind of words feel good to hear. Agree to avoid comments on each other bodies and revisit in a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciate about you"}, {"id": "f1", "type": "textarea", "label": "Partner B: something I appreciate about you"}, {"id": "f2", "type": "textarea", "label": "Words that feel good to hear"}, {"id": "f3", "type": "textarea", "label": "Comments we will leave out"}, {"id": "f4", "type": "textarea", "label": "How we will remind each other"}]'::jsonb, array['body image', 'couples', 'connection']::text[], '2026-10-04T15:00:00+00:00'::timestamptz),
  ('superhero-body-powers-drawing', 'Superhero Body Powers Drawing', 'kids'::resource_kind, 'A child draws themselves as a superhero with powers based on what their body can do.', 'Help a child value what the body does rather than how it looks.', array['Children']::text[], '30 minutes', 'Invite the child to design a superhero version of themselves with powers like fast legs or strong hugs, and talk about what real body helps them do. The parent joins in and comments only on what the child does, not looks. Follow reporting duties if harm is disclosed.', '[{"id": "f0", "type": "textarea", "label": "My superhero name"}, {"id": "f1", "type": "textarea", "label": "My body powers"}, {"id": "f2", "type": "textarea", "label": "A real thing my body helped me do"}, {"id": "f3", "type": "textarea", "label": "What my parent noticed"}, {"id": "f4", "type": "textarea", "label": "How I want to use my powers"}]'::jsonb, array['body image', 'children', 'play']::text[], '2026-10-04T15:00:00+00:00'::timestamptz)
